// Tier 1: Flashcard Data  -  All 9 Domains, BACB 6th Edition TCO
// Each card: term (front), definition (back), domain

export interface Flashcard {
  id: string;
  term: string;
  definition: string;
  domain: string;
  domainFull: string;
  example?: string;
}

export const flashcards: Flashcard[] = [
  { id: 'a1', term: 'Applied Behavior Analysis (ABA)', definition: 'The science in which the principles of behavior are applied systematically to improve socially significant behavior, and experimentation is used to identify the variables responsible for behavior change.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'Teaching Leo to request items using words instead of tantrums is an application of ABA.' },
  { id: 'a2', term: 'Selectionism', definition: 'The philosophical position that behavior is selected by its consequences across three levels: phylogenic (species history), ontogenic (individual history), and cultural (group practices).', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations' },
  { id: 'a3', term: 'Radical Behaviorism', definition: "Skinner's philosophy of behavioral science that includes all behavior  -  public and private  -  within the subject matter of behavior analysis, rejecting mentalistic explanations while acknowledging internal events as behaviors.", domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations' },
  { id: 'a4', term: 'Methodological Behaviorism', definition: 'A philosophical position that limits the subject matter of psychology to publicly observable behavior, excluding private events (thoughts, feelings) from scientific analysis.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations' },
  { id: 'a5', term: 'Determinism', definition: 'The assumption that behavior is lawful and caused by identifiable, environmental variables  -  not by free will or internal mentalistic causes.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations' },
  { id: 'a6', term: 'Empiricism', definition: 'The practice of relying on direct observation and objective measurement of behavior rather than subjective opinion or inference.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations' },
  { id: 'a7', term: 'Parsimony', definition: 'The scientific principle of adopting the simplest, most logical explanation for behavior before considering more complex or mentalistic accounts.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations' },
  { id: 'a8', term: 'Mentalism', definition: 'The practice of explaining behavior by reference to hypothetical internal states or constructs (e.g., "he hit because he is angry") that are not directly observable or measurable.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations' },
  { id: 'a9', term: 'Pragmatism', definition: 'A philosophical position that evaluates the truth or value of a concept by its practical consequences; in ABA, interventions are judged by whether they produce meaningful, observable behavior change.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA selects an intervention based on its demonstrated effectiveness, not theoretical elegance.' },
  { id: 'a10', term: 'Private Events', definition: 'Behaviors (thoughts, feelings, physiological states) that occur within the skin of an organism and are accessible only to that individual; treated as behavior subject to the same laws as overt behavior in radical behaviorism.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A client reports feeling anxious; the BCBA treats this self-report as verbal behavior, not as a cause of avoidance.' },
  { id: 'a14', term: 'Cultural Contingencies', definition: 'Practices and behaviors transmitted across generations within a social group through verbal and nonverbal means; a third level of selection that shapes the behavior of individuals within a culture.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations' },
  { id: 'a15', term: 'Skepticism', definition: 'The scientific disposition to withhold judgment until sufficient evidence has been gathered; in ABA, practitioners require empirical support before adopting new interventions.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations' },
  { id: 'a19', term: 'Experimentation', definition: 'A scientific method in which the researcher systematically manipulates one or more independent variables while measuring the effect on a dependent variable under controlled conditions, in order to establish a cause-and-effect relationship.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A researcher manipulates the density of a reinforcement schedule (IV) and measures the rate of a target response (DV) across conditions, demonstrating that schedule density causes changes in response rate.' },
  { id: 'a20', term: 'Replication', definition: 'The repetition of an experiment or its results, either within the same study (direct replication) or across different subjects, settings, or experimenters (systematic replication), to establish the reliability and generality of a finding.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA demonstrates that an FCT intervention reduces aggression with three different clients in two different settings  -  systematic replication that increases confidence in the procedure\'s generality.' },
  { id: 'a21', term: 'Philosophical Doubt', definition: 'The scientific attitude of treating all currently accepted knowledge as tentative and subject to revision in light of new evidence; a commitment to questioning assumptions and remaining open to disconfirming data rather than defending established positions.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA who has used a particular intervention successfully for years continues to monitor data critically and is willing to abandon the procedure if new evidence demonstrates a more effective alternative.' },
  { id: 'a26', term: 'Overt Behavior', definition: 'Any action of an organism that is publicly observable and directly measurable by an external observer without special instrumentation; the primary subject matter of methodological behaviorism and a key focus of applied behavior analysis.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A student raising their hand, hitting a peer, or completing a math worksheet are all overt behaviors that a BCBA can directly observe and record using frequency, duration, or interval recording.' },
  { id: 'a27', term: 'Covert Behavior', definition: 'Any action of an organism that occurs at a level of intensity too small to be observed by others, or that takes place entirely within the organism\'s skin; in radical behaviorism, these are treated as real behaviors governed by the same principles as overt behavior, not as causes of overt behavior.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'Subvocal rehearsal (thinking through the steps of a task), imagining a feared stimulus, or feeling muscle tension are covert behaviors that influence overt responding but are not directly accessible to an external observer.' },
  { id: 'a28', term: 'Behaviorism', definition: 'The philosophy of science that defines behavior  -  including the behavior of organisms as a whole  -  as the proper subject matter of psychology, and holds that a complete account of behavior can be achieved by identifying the environmental variables that control it, without invoking unobservable mental entities as explanatory causes.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A behaviorist explains a child\'s refusal to attend school by analyzing the antecedent conditions (e.g., test day) and consequences (e.g., escape from aversive evaluation) rather than attributing the behavior to anxiety as an internal cause.' },
  { id: 'a29', term: 'Experimental Analysis of Behavior (EAB)', definition: 'The basic science of behavior that uses controlled laboratory methods  -  typically with individual organisms under precisely arranged contingencies  -  to identify the fundamental principles governing the relationships between behavior and environmental variables; the scientific foundation from which applied behavior analysis derives its principles.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'Skinner\'s laboratory research with pigeons and rats established the principles of reinforcement schedules (e.g., fixed ratio, variable interval) that EAB identified and that ABA practitioners later applied to human behavior change.' },
  { id: 'a31', term: 'Professional Practice (in Behavior Analysis)', definition: 'The service delivery context in which credentialed behavior analysts apply the principles and procedures of applied behavior analysis to individual clients, operating under ethical codes, regulatory requirements, and organizational constraints that govern the responsible delivery of behavioral services.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA working in a school district applies ABA procedures to reduce a student\'s problem behavior, but must also obtain informed consent, document services for billing, supervise RBTs, and adhere to BACB ethics standards  -  all elements of professional practice.' },
  { id: 'a32', term: 'Behavioral (Dimension of ABA)', definition: 'The dimension of applied behavior analysis requiring that the subject matter be a directly measurable aspect of the behavior of interest, rather than a score on a test, a rating, or an inferred construct; the behavior itself must be observed and quantified.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA measures the frequency of a student\'s hand-raising responses directly during class, rather than relying on a teacher\'s rating of the student\'s "participation level"  -  ensuring the study is behavioral.' },
  { id: 'a33', term: 'Applied (Dimension of ABA)', definition: 'The dimension of applied behavior analysis requiring that the behaviors and environmental variables selected for study be of demonstrable importance to the individual or to society, not merely of theoretical interest; the social significance of the target must be justified.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA targets a child\'s self-injurious behavior for reduction because it poses a physical danger and limits participation in school  -  a behavior of clear social importance  -  rather than targeting a behavior of only academic interest.' },
  { id: 'a34', term: 'Technological (Dimension of ABA)', definition: 'The dimension of applied behavior analysis requiring that procedures be described with sufficient precision and completeness that any trained practitioner could implement them accurately without additional information from the original researcher or clinician.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA writes a behavior intervention plan that specifies the exact antecedent prompt, the reinforcer, the reinforcement schedule, the error correction procedure, and the mastery criterion  -  enabling any trained RBT to implement it with fidelity.' },
  { id: 'a35', term: 'Conceptually Systematic (Dimension of ABA)', definition: 'The dimension of applied behavior analysis requiring that procedures and interpretations be described in terms of the established principles of behavior from which they are derived, linking applied work back to the basic science and its theoretical framework.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA describes an FCT procedure not merely as "teaching the child to ask for breaks" but as establishing a mand on a dense schedule of reinforcement to compete with the escape function of problem behavior  -  linking the procedure to reinforcement and motivating operation principles.' },
  { id: 'a36', term: 'Analytic (Dimension of ABA)', definition: 'The dimension of applied behavior analysis requiring that the practitioner demonstrate a reliable, functional relationship between the intervention (independent variable) and the behavior change (dependent variable), typically through the use of a single-subject experimental design.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA uses an ABAB reversal design to show that problem behavior decreases when the intervention is in place and returns toward baseline when it is withdrawn  -  demonstrating experimental control and satisfying the analytic dimension.' },
  { id: 'a37', term: 'Generality (Dimension of ABA)', definition: 'The dimension of applied behavior analysis requiring that behavior changes prove durable over time, appear across a variety of settings and conditions, and spread to a range of related behaviors beyond those directly trained; the extent to which outcomes are broadly useful to the individual.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA confirms that a student\'s newly acquired manding skill is maintained at a 3-month follow-up, occurs in the classroom and at home (not only in the therapy room), and has generalized to novel communication partners  -  demonstrating generality.' },
  { id: 'a38', term: 'Effective (Dimension of ABA)', definition: 'The dimension of applied behavior analysis requiring that interventions produce behavior changes of practical and social significance  -  not merely statistically detectable differences  -  that make a real difference in the life of the individual and those around them.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA\'s intervention reduces a client\'s self-injury from an average of 45 incidents per day to fewer than 2, enabling the client to attend school and participate in family activities  -  a change that is effective in the socially meaningful sense, not merely statistically significant.' },
  { id: 'a39', term: 'Science', definition: 'A systematic approach to understanding natural phenomena through empirical observation, controlled experimentation, and objective analysis; characterized by the goals of description, prediction, and control of the subject matter.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'A BCBA uses direct observation, data collection, and experimental design to study the relationship between a reinforcement schedule and a client\'s response rate — applying the methods of science to behavior.' },
  { id: 'a41', term: 'Functional Relation', definition: 'A demonstrated, reliable relationship between a specific environmental variable (independent variable) and a change in behavior (dependent variable), such that the behavior changes when and only when the environmental variable is manipulated.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'After demonstrating through a reversal design that self-injury increases during demand conditions and decreases when demands are removed, a BCBA concludes that a functional relation exists between escape from demands and self-injury.' },
  { id: 'a42', term: 'Hypothetical Construct', definition: 'An invented, unobservable entity or process used to explain behavior, which cannot be directly measured or verified; behavior analysts reject hypothetical constructs as explanations because they do not identify actual environmental causes.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'Explaining a child\'s aggression by saying they have "low frustration tolerance" invokes a hypothetical construct — an inferred internal state that cannot be directly observed — rather than identifying the specific environmental antecedents and consequences that control the behavior.' },
  { id: 'a43', term: 'Explanatory Fiction', definition: 'A circular, pseudo-explanation that names a behavior and then uses that name as the cause of the behavior, creating the illusion of explanation without identifying any actual environmental variable.', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations', example: 'Saying "Marcus hits because he is aggressive" is an explanatory fiction — the term "aggressive" is derived from the hitting behavior itself and does not identify any environmental cause; it adds no explanatory value.' },
  { id: 'b1', term: 'Positive Reinforcement', definition: 'A procedure in which a stimulus is added following a behavior, resulting in an increase in the future frequency of that behavior.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Leo receives praise after completing a math problem; he completes more problems in the future.' },
  { id: 'b2', term: 'Negative Reinforcement', definition: 'A procedure in which a stimulus is removed following a behavior, resulting in an increase in the future frequency of that behavior.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Leo tantrums; the teacher removes the math worksheet; tantrums increase.' },
  { id: 'b3', term: 'Positive Punishment', definition: 'A procedure in which a stimulus is added following a behavior, resulting in a decrease in the future frequency of that behavior.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child runs in the hallway; the teacher requires him to walk back and forth five times (positive practice overcorrection). Running decreases over the following week.' },
  { id: 'b4', term: 'Negative Punishment', definition: 'A procedure in which a stimulus is removed following a behavior, resulting in a decrease in the future frequency of that behavior.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A student loses two tokens from her token board each time she engages in verbal aggression (response cost). Verbal aggression decreases over three weeks.' },
  { id: 'b5', term: 'Extinction', definition: 'The discontinuation of a reinforcement contingency that previously maintained a behavior, resulting in a decrease in the future frequency of that behavior.', domain: 'B', domainFull: 'Concepts & Principles', example: "A child's tantrums were maintained by caregiver attention. The BCBA instructs the caregiver to withhold all attention following tantrums. After an initial extinction burst, tantrums decrease to near zero over four weeks." },
  { id: 'b6', term: 'Motivating Operation (MO)', definition: 'An environmental variable that (1) alters the reinforcing or punishing effectiveness of a stimulus (value-altering effect) and (2) alters the frequency of behavior that has been reinforced or punished by that stimulus (behavior-altering effect).', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child who has not had tablet access for three hours (deprivation = EO) requests it more frequently and works harder to earn it. After 30 minutes of access (satiation = AO), requesting decreases and the tablet functions as a weaker reinforcer.' },
  { id: 'b7', term: 'Establishing Operation (EO)', definition: 'A motivating operation that increases the reinforcing effectiveness of a stimulus and increases the current frequency of behavior that has been reinforced by that stimulus.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Food deprivation is an EO that makes food more reinforcing and increases food-seeking behavior.' },
  { id: 'b8', term: 'Abolishing Operation (AO)', definition: 'A motivating operation that decreases the reinforcing effectiveness of a stimulus and decreases the current frequency of behavior that has been reinforced by that stimulus.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Satiation is an AO  -  after eating, food is less reinforcing and food-seeking behavior decreases.' },
  { id: 'b9', term: 'Discriminative Stimulus (SD)', definition: 'A stimulus in the presence of which a particular behavior has been reinforced and in the absence of which that behavior has not been reinforced; it signals that reinforcement is available.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child reliably requests a snack when the kitchen light is on (SD  -  requests have been reinforced there) but not when the light is off (SΔ  -  requests have not been reinforced in that context).' },
  { id: 'b10', term: 'S-Delta (SΔ)', definition: 'A stimulus in the presence of which a particular behavior has not been reinforced; it signals that reinforcement is not available.', domain: 'B', domainFull: 'Concepts & Principles', example: 'During DTT, the therapist presents a picture of a dog as the SD. A picture of a cat is the SΔ  -  selecting the cat has never been reinforced, so the child learns to respond only to the dog picture.' },
  { id: 'b11', term: 'Stimulus Control', definition: 'A condition in which the frequency, latency, duration, or amplitude of a behavior is altered by the presence or absence of an antecedent stimulus.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A student completes work when the classroom teacher is present but engages in off-task behavior when a substitute is present  -  the teacher has acquired stimulus control over on-task behavior.' },
  { id: 'b12', term: 'Stimulus Generalization', definition: 'The occurrence of a behavior in the presence of stimuli that are similar to but not identical to the training stimulus.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child is taught to greet her BCBA by saying "hi." Without additional training, she also greets her teacher, parents, and peers  -  the greeting response has generalized to novel people.' },
  { id: 'b13', term: 'Response Generalization', definition: 'The occurrence of untrained responses that are functionally similar to the trained response when the trained stimulus is presented.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child is taught to say "hi" as a greeting. Without direct training, he also begins waving and nodding when he sees familiar people  -  new but functionally equivalent greeting responses have emerged.' },
  { id: 'b14', term: 'Stimulus Discrimination', definition: 'The differential responding to two or more stimuli; responding occurs in the presence of the SD but not in the presence of the SΔ.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child correctly labels a picture of a dog as "dog" (SD) and does not label a picture of a cat as "dog" (SΔ)  -  she has learned to discriminate between the two stimuli.' },
  { id: 'b15', term: 'Shaping', definition: 'The differential reinforcement of successive approximations to a target behavior; reinforcement is delivered for responses that progressively resemble the terminal behavior.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A nonverbal child is taught to say "ball." The BCBA first reinforces any vocalization, then only "b" sounds, then "ba," then "ball"  -  each previous approximation is placed on extinction as the next criterion is introduced.' },
  { id: 'b16', term: 'Chaining', definition: 'A procedure for teaching a sequence of behaviors (a behavior chain) in which each behavior in the chain serves as an SD for the next behavior and as a conditioned reinforcer for the preceding behavior.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA uses a task analysis to teach hand-washing as a 10-step chain. Completing step 1 (turn on faucet) is the SD for step 2 (wet hands)  -  each step is both a conditioned reinforcer for the previous step and an SD for the next.' },
  { id: 'b17', term: 'Conditioned Reinforcer', definition: 'A stimulus that has acquired reinforcing function through a history of pairing with other reinforcers; also called secondary reinforcer.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Tokens initially have no reinforcing value. After being consistently paired with access to preferred items, a child begins working hard to earn tokens even when the backup reinforcers are not immediately visible.' },
  { id: 'b18', term: 'Unconditioned Reinforcer', definition: 'A stimulus that functions as a reinforcer without any prior learning history; its reinforcing value is biologically determined (e.g., food, water, warmth).', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child who has not eaten for several hours reliably works for small pieces of preferred food  -  the food functions as an unconditioned reinforcer because its value does not depend on prior learning.' },
  { id: 'b19', term: 'Automatic Reinforcement', definition: 'Reinforcement that is produced directly by the behavior itself, independent of the social mediation of another person.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child engages in hand-flapping at the same rate whether or not adults are present and regardless of whether they provide attention or ignore it  -  the sensory stimulation produced by the behavior itself maintains it.' },
  { id: 'b20', term: 'Social Reinforcement', definition: 'Reinforcement delivered by another person (e.g., praise, attention, access to preferred activities provided by others).', domain: 'B', domainFull: 'Concepts & Principles', example: 'A student raises her hand and the teacher calls on her and praises her answer. Her hand-raising increases  -  the teacher\'s attention and praise (delivered by another person) are functioning as social reinforcers.' },
  { id: 'b21', term: 'Mand', definition: "A verbal operant in which the speaker's response is evoked by a motivating operation and is reinforced by a characteristic consequence (the speaker gets what they asked for).", domain: 'B', domainFull: 'Concepts & Principles', example: 'Leo says "cookie" when hungry and receives a cookie.' },
  { id: 'b22', term: 'Tact', definition: 'A verbal operant in which the response is evoked by a nonverbal discriminative stimulus (an object, event, or property) and is reinforced by generalized conditioned reinforcement.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Leo sees a dog and says "dog."' },
  { id: 'b23', term: 'Intraverbal', definition: 'A verbal operant in which the response is evoked by a verbal discriminative stimulus and the response does not have point-to-point correspondence with that stimulus.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Asked "What do you do when you are hungry?" Leo says "eat."' },
  { id: 'b24', term: 'Echoic', definition: 'A verbal operant in which the response is evoked by a verbal discriminative stimulus and has point-to-point correspondence and formal similarity with that stimulus (vocal imitation).', domain: 'B', domainFull: 'Concepts & Principles', example: 'The therapist says "ball" and the child immediately says "ball"  -  the vocal response matches the verbal model exactly in sound and form.' },
  { id: 'b25', term: 'Textual', definition: 'A verbal operant in which the response is evoked by a visual verbal discriminative stimulus (written text) and has point-to-point correspondence but not formal similarity (reading aloud).', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child sees the written word "cat" on a flashcard and says "cat" aloud  -  the spoken response corresponds point-to-point with the written text, but the two forms (visual vs. vocal) are not formally similar.' },
  { id: 'b26', term: 'Transcription', definition: 'A verbal operant in which the response is evoked by a verbal discriminative stimulus and has point-to-point correspondence and formal similarity, but the response is written rather than spoken (writing from dictation).', domain: 'B', domainFull: 'Concepts & Principles', example: 'A teacher says "cat" and the student writes "cat" on paper  -  the written response has point-to-point correspondence and formal similarity (both are the word "cat") with the spoken stimulus.' },
  { id: 'b27', term: 'Autoclitic', definition: 'A verbal operant that is evoked by other verbal behavior of the speaker and functions to modify the effect of that verbal behavior on the listener.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child says "I think it is a dog"  -  the autoclitic "I think" modifies the listener\'s response to the tact "dog" by signaling uncertainty, changing how the listener acts on the information.' },
  { id: 'b28', term: 'Rule-Governed Behavior', definition: 'Behavior controlled by a verbal description of a contingency (a rule), rather than by direct contact with the contingency.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child stops at a red light because she was told "red means stop," not because she has ever experienced a consequence for running a red light  -  the verbal rule controls her behavior.' },
  { id: 'b29', term: 'Contingency-Shaped Behavior', definition: 'Behavior that has been shaped by direct contact with the three-term contingency (antecedent → behavior → consequence), without the mediation of verbal rules.', domain: 'B', domainFull: 'Concepts & Principles', example: 'An experienced tennis player adjusts her grip and stance fluidly during a match  -  these fine motor adjustments were shaped by years of direct reinforcement and punishment contingencies, not by following verbal instructions.' },
  { id: 'b30', term: 'Extinction Burst', definition: 'A temporary increase in the frequency, duration, or intensity of a behavior when extinction is first implemented.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child\'s tantrums were maintained by attention. On the first day of extinction, tantrums increase from 3 per hour to 12 per hour and become louder before gradually decreasing over the following days.' },
  { id: 'b31', term: 'Spontaneous Recovery', definition: 'The reappearance of an extinguished behavior after a period of time has elapsed since extinction was implemented.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child\'s tantrums decreased to zero after four weeks of extinction. After a weekend break, tantrums reappear at low rates on Monday morning  -  this is spontaneous recovery, not a treatment failure.' },
  { id: 'b32', term: 'Resurgence', definition: 'The reappearance of a previously extinguished behavior when a more recently reinforced behavior is placed on extinction.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Tantrums were extinguished and replaced with functional communication (FCT). When the FCT response is accidentally placed on extinction (e.g., caregiver stops responding), the original tantrums resurge even though they were previously eliminated.' },
  { id: 'b33', term: 'Convergent Multiple Control', definition: 'A condition in which a single verbal response is controlled by more than one variable simultaneously.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child says "apple" because she sees an apple (tact), is hungry (MO-evoked mand), and just heard someone say "apple" (echoic)  -  multiple variables converge to produce a single verbal response.' },
  { id: 'b34', term: 'Divergent Multiple Control', definition: 'A condition in which a single variable affects more than one verbal response.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Seeing a fire truck (single stimulus) evokes multiple verbal responses: "truck," "red," "loud," and "fire"  -  one antecedent variable controls several different verbal operants simultaneously.' },
  { id: 'b35', term: 'Continuous Reinforcement (CRF)', definition: 'A schedule of reinforcement in which every occurrence of the target behavior produces a reinforcer; used during initial skill acquisition to establish behavior quickly. Note: CRF is a foundational concept distinct from intermittent schedules  -  it is the densest possible schedule and produces the fastest acquisition but also the fastest extinction.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Every time Leo says "ball," the therapist immediately delivers the ball. Each correct response is reinforced on a CRF schedule to establish the mand quickly.' },
  { id: 'b36', term: 'Fixed Ratio (FR) Schedule', definition: 'A schedule of reinforcement in which a reinforcer is delivered after a fixed, predetermined number of responses; produces high, steady rates with a post-reinforcement pause.', domain: 'B', domainFull: 'Concepts & Principles', example: 'FR5: a student earns a token after every 5 correct responses.' },
  { id: 'b37', term: 'Variable Ratio (VR) Schedule', definition: 'A schedule of reinforcement in which a reinforcer is delivered after an average number of responses that varies around a mean; produces high, steady rates and is highly resistant to extinction.', domain: 'B', domainFull: 'Concepts & Principles', example: 'VR10: a reinforcer is delivered on average every 10 responses, but the exact number varies unpredictably.' },
  { id: 'b38', term: 'Fixed Interval (FI) Schedule', definition: 'A schedule of reinforcement in which a reinforcer is delivered for the first response after a fixed period of time has elapsed; produces a scallop pattern with low rates after reinforcement and accelerating rates as the interval ends.', domain: 'B', domainFull: 'Concepts & Principles', example: 'FI 5-min: a child earns a token for the first correct response after 5 minutes have elapsed. Responding is low immediately after earning a token and increases as the 5-minute mark approaches.' },
  { id: 'b39', term: 'Variable Interval (VI) Schedule', definition: 'A schedule of reinforcement in which a reinforcer is delivered for the first response after a variable amount of time has elapsed; produces moderate, steady response rates and is resistant to extinction.', domain: 'B', domainFull: 'Concepts & Principles', example: 'VI 3-min: a child earns praise for the first on-task response after an average of 3 minutes, but the exact interval varies (e.g., 1 min, 4 min, 2 min). Responding is steady and consistent throughout the session.' },
  { id: 'b40', term: 'Intermittent Reinforcement', definition: 'A schedule of reinforcement in which only some occurrences of the target behavior produce a reinforcer; used to maintain behavior and increase resistance to extinction after initial acquisition.', domain: 'B', domainFull: 'Concepts & Principles', example: 'After a child has mastered requesting with 100% accuracy on CRF, the BCBA thins the schedule to VR3 (every 3rd request on average) to build resistance to extinction and promote maintenance.' },
  { id: 'b41', term: 'Respondent Conditioning (Classical Conditioning)', definition: 'A form of learning in which a neutral stimulus acquires the ability to elicit a response by being repeatedly paired with an unconditioned stimulus that already elicits that response.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child cries at the sight of a white coat after repeated painful injections in a medical office.' },
  { id: 'b42', term: 'Unconditioned Stimulus (US)', definition: 'A stimulus that elicits a reflexive response without prior learning; also called an unlearned or unconditional stimulus.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A loud unexpected noise (US) automatically elicits a startle response (UR) in a child without any prior conditioning  -  the reflex is biologically wired.' },
  { id: 'b43', term: 'Conditioned Stimulus (CS)', definition: 'A previously neutral stimulus that, after repeated pairing with an unconditioned stimulus, comes to elicit a conditioned response.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A white lab coat (originally neutral) is repeatedly paired with painful injections (US). The white coat becomes a CS  -  the child now cries and pulls away when she sees the coat, before any injection occurs.' },
  { id: 'b44', term: 'Unconditioned Response (UR)', definition: 'A reflexive, unlearned response elicited by an unconditioned stimulus; occurs reliably without prior conditioning.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Crying and flinching in response to a painful injection (US)  -  this reflexive response occurs without any learning history and is the UR in a respondent conditioning chain.' },
  { id: 'b45', term: 'Conditioned Response (CR)', definition: 'A learned response elicited by a conditioned stimulus after respondent conditioning; typically resembles but may differ in magnitude from the unconditioned response.', domain: 'B', domainFull: 'Concepts & Principles', example: 'After repeated pairings of a white coat (CS) with painful injections, a child begins crying when she sees the white coat alone  -  this learned crying is the CR, which resembles but is typically less intense than the UR.' },
  { id: 'b46', term: 'Stimulus Equivalence', definition: 'A set of untrained and emergent relations among stimuli (reflexivity, symmetry, transitivity) that arise from conditional discrimination training; demonstrates derived relational responding.', domain: 'B', domainFull: 'Concepts & Principles', example: 'After training A→B and B→C, a student demonstrates B→A, C→B, A→C, and C→A without direct training.' },
  { id: 'b47', term: 'Reflexivity (Stimulus Equivalence)', definition: 'The emergent relation in which a stimulus is shown to be equivalent to itself (A=A); demonstrated by a matching-to-sample response without direct training.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child is shown a picture of a dog as the sample and three pictures as comparisons (dog, cat, ball). Without training, she selects the matching dog picture  -  demonstrating that the stimulus is equivalent to itself.' },
  { id: 'b48', term: 'Symmetry (Stimulus Equivalence)', definition: 'The emergent bidirectional relation between two stimuli (if A→B, then B→A) that arises without direct training; one of three defining properties of stimulus equivalence.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child is trained to select a picture of a dog when given the spoken word "dog" (A→B). Without further training, she also selects the spoken word "dog" when shown the picture (B→A)  -  the relation has emerged bidirectionally.' },
  { id: 'b49', term: 'Transitivity (Stimulus Equivalence)', definition: 'The emergent relation in which two stimuli each related to a third stimulus become related to each other (if A→B and B→C, then A→C) without direct training.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child is trained: spoken "dog" → picture of dog (A→B) and picture of dog → written word DOG (B→C). Without training, she selects the written word DOG when she hears "dog" (A→C)  -  transitivity has emerged.' },
  { id: 'b50', term: 'Matching Law', definition: 'A quantitative principle stating that the relative rate of responding on a concurrent schedule matches the relative rate of reinforcement obtained; describes how organisms distribute behavior across alternatives. Note: This describes an idealized mathematical relationship; real behavior often shows undermatching or overmatching.', domain: 'B', domainFull: 'Concepts & Principles', example: 'If appropriate requests are reinforced 80% of the time and problem behavior is reinforced 20% of the time, the matching law predicts the child will use appropriate requests 80% of the time  -  a key rationale for FCT.' },
  { id: 'b51', term: 'Concurrent Schedules', definition: 'Two or more schedules of reinforcement that are simultaneously available; the organism can freely switch between alternatives, and behavior distribution is described by the matching law.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child can either request a break (reinforced on VR2) or engage in problem behavior (reinforced on VR5). Because requesting produces reinforcement more frequently, the child allocates more behavior to requesting  -  consistent with the matching law.' },
  { id: 'b53', term: 'Unconditioned Punisher', definition: 'A stimulus that decreases the future frequency of behavior it follows without prior learning; its punishing function is determined by the organism\'s biology and evolutionary history.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child touches a hot stove; the pain (unconditioned punisher) decreases future stove-touching without any prior conditioning history.' },
  { id: 'b54', term: 'Conditioned Punisher', definition: 'A previously neutral stimulus that acquires punishing properties through pairing with an unconditioned or established punisher; its effectiveness depends on learning history.', domain: 'B', domainFull: 'Concepts & Principles', example: 'The word "No!" becomes a conditioned punisher after repeated pairing with loss of preferred items; it now decreases behavior when presented alone.' },
  { id: 'b55', term: 'Generalized Conditioned Punisher', definition: 'A conditioned punisher that has been paired with multiple other punishers and therefore suppresses behavior across a wide range of motivating conditions; its effectiveness does not depend on a specific establishing operation.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Social disapproval (frowning, criticism) functions as a generalized conditioned punisher because it has been paired with many different aversive consequences across the individual\'s learning history.' },
  { id: 'b56', term: 'Multiple Schedule', definition: 'A compound schedule of reinforcement in which two or more component schedules alternate, each signaled by a distinct discriminative stimulus; the organism must respond according to whichever schedule is currently in effect.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A green light signals a VI 30-s schedule; a red light signals extinction. The organism learns to respond during the green light and pause during the red light.' },
  { id: 'b57', term: 'Mixed Schedule', definition: 'A compound schedule of reinforcement in which two or more component schedules alternate without any discriminative stimulus signaling which component is in effect; unlike a multiple schedule, no external cue differentiates the components.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child\'s requests are sometimes reinforced on FR 1 and sometimes on extinction, with no signal indicating which is in effect  -  producing variable and often persistent responding.' },
  { id: 'b58', term: 'Chained Schedule', definition: 'A compound schedule in which completion of each component produces a conditioned reinforcer (the SD for the next component) and access to the next component; the terminal reinforcer is delivered only upon completion of the final link.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child must complete a work task (Link 1: FR 5) to earn a token (conditioned reinforcer and SD for Link 2), then exchange the token (Link 2: FR 1) to access preferred items (terminal reinforcer).' },
  {
    id: 'b62',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Antecedent',
    definition: 'Any environmental condition or change in condition that precedes a behavior and may influence its occurrence.',
    example: 'The therapist places a preferred toy on the table (antecedent) before asking the child to sit down.',
  },
  {
    id: 'b63',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Reinforcer',
    definition: 'A stimulus whose presentation or removal following a behavior increases the future frequency of that behavior under similar conditions.',
    example: 'Praise delivered after a student completes a math problem increases the rate of problem completion.',
  },
  {
    id: 'b64',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Automatic Contingency',
    definition: 'A reinforcing or punishing consequence that is produced directly by the behavior itself, without mediation by another person.',
    example: 'A child hums to herself because the auditory stimulation produced by humming is itself reinforcing.',
  },
  {
    id: 'b66',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Repertoire',
    definition: 'The total collection of behaviors a person is capable of performing at a given time, shaped by learning history and biology.',
    example: 'A BCBA assesses a child\'s verbal repertoire to determine which mands, tacts, and intraverbals are present.',
  },
  {
    id: 'b67',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Automaticity of Reinforcement',
    definition: 'The property of reinforcement that describes how it strengthens behavior without requiring the organism to be aware of or understand the contingency.',
    example: 'A child\'s self-stimulatory behavior is maintained automatically even though the child cannot describe why they engage in it.',
  },
  {
    id: 'b69',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Respondent Behavior',
    definition: 'Behavior that is elicited by an antecedent stimulus and occurs reflexively, without requiring prior learning of the specific stimulus-response relationship.',
    example: 'Pupil dilation in dim light and salivation to food in the mouth are examples of respondent behaviors.',
  },
  {
    id: 'b70',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Aversive Stimulus',
    definition: 'A stimulus whose presentation decreases the future frequency of behavior it follows (punisher), or whose removal increases the future frequency of behavior it follows (negative reinforcer).',
    example: 'Loud noise functions as an aversive stimulus when its termination reinforces the behavior of putting on earplugs.',
  },
  {
    id: 'b71',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Joint Control',
    definition: 'A verbal behavior phenomenon in which a speaker\'s selection of a response is controlled by both a verbal stimulus and a nonverbal stimulus simultaneously.',
    example: 'A child asked to "find the red ball" must match the spoken word "red" to the visual property of the ball before responding.',
  },
  {
    id: 'b72',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Behavior',
    definition: 'The activity of living organisms; any muscular, glandular, or electrical activity of an organism that can be measured.',
    example: 'Talking, walking, thinking, and heart rate are all behaviors because they are measurable activities of a living organism.',
  },
  {
    id: 'b74',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Response',
    definition: 'A single instance of a behavior; one occurrence of a specific action by an organism.',
    example: 'Each time a student raises their hand to answer a question, that constitutes one response.',
  },
  {
    id: 'b75',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Conditioned Reflex',
    definition: 'A learned stimulus-response relationship in which a previously neutral stimulus acquires the ability to elicit a response through repeated pairing with an unconditioned stimulus.',
    example: 'A child who has been repeatedly hurt during dental procedures cries when entering the dental office.',
  },
  {
    id: 'b76',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Neutral Stimulus',
    definition: 'A stimulus that, prior to conditioning, does not elicit the response of interest and has no established reinforcing or punishing function.',
    example: 'A metronome is a neutral stimulus before it is paired with food in a Pavlovian conditioning procedure.',
  },
  {
    id: 'b77',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Ontogeny',
    definition: 'The behavioral and biological development of an individual organism across its lifetime, shaped by both genetic endowment and learning history.',
    example: 'A child\'s verbal behavior repertoire develops through ontogeny as a result of reinforcement provided by caregivers.',
  },
  {
    id: 'b79',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Operant Behavior',
    definition: 'Behavior that is selected, maintained, and brought under stimulus control by its consequences; behavior that operates on the environment to produce consequences.',
    example: 'Pressing a lever to obtain food is operant behavior because it is maintained by its consequence (food delivery).',
  },
  {
    id: 'b80',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Socially Mediated Contingency',
    definition: 'A reinforcement or punishment contingency in which the consequence is delivered by another person rather than produced directly by the behavior itself.',
    example: 'A teacher providing praise after a student answers correctly is a socially mediated reinforcement contingency.',
  },
  {
    id: 'b81',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Consequence',
    definition: 'A stimulus change that follows a behavior and may increase or decrease the future frequency of that behavior.',
    example: 'The delivery of a token following correct responding is a consequence that increases future responding.',
  },
  {
    id: 'b82',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Operant Conditioning',
    definition: 'A type of learning in which the future frequency of a behavior is modified by its consequences; behavior is strengthened by reinforcement and weakened by punishment or extinction.',
    example: 'A rat learns to press a lever more frequently when lever presses produce food pellets — an example of operant conditioning.',
  },
  {
    id: 'b83',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Stimulus',
    definition: 'Any energy change in the environment that affects an organism\'s sensory receptors and may influence behavior.',
    example: 'A flashing light, a spoken word, and a change in room temperature are all stimuli that can influence behavior.',
  },
  {
    id: 'b84',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Contingency',
    definition: 'A conditional relationship between a behavior and an antecedent or consequent event; the "if-then" relationship specifying when and how consequences follow behavior.',
    example: 'The contingency "if the student completes 10 problems, then they earn 5 minutes of free time" describes a fixed-ratio reinforcement schedule.',
  },
  {
    id: 'b85',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Phylogeny',
    definition: 'The evolutionary history of a species; the biological endowment that determines which stimuli can function as reinforcers or punishers without prior learning.',
    example: 'Humans\' phylogenetic history makes food, water, and warmth function as unconditioned reinforcers.',
  },
  {
    id: 'b86',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Contingent',
    definition: 'Describes a consequence that is delivered only when a specific behavior occurs; the consequence depends on the behavior.',
    example: 'Praise is contingent on correct responding when it is delivered only after the student answers correctly, not at other times.',
  },
  {
    id: 'b87',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Stimulus-Stimulus Pairing',
    definition: 'A procedure in which two stimuli are presented together repeatedly, so that one stimulus acquires the reinforcing or eliciting properties of the other.',
    example: 'Pairing a therapist\'s voice with preferred items can make the therapist\'s voice a conditioned reinforcer.',
  },
  {
    id: 'b88',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Deprivation',
    definition: 'A condition in which access to a specific reinforcer has been withheld or reduced, increasing the current reinforcing value of that stimulus.',
    example: 'A child who has not had access to a preferred toy for several hours will show increased motivation to obtain that toy.',
  },
  {
    id: 'b90',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Three-Term Contingency',
    definition: 'The fundamental unit of operant analysis consisting of an antecedent stimulus, a behavior, and a consequence; also called the ABCs of behavior.',
    example: 'SD (teacher says "sit down") → B (student sits) → C (teacher delivers praise) is a three-term contingency.',
  },
  {
    id: 'b91',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Discriminated Operant',
    definition: 'An operant behavior that occurs more frequently in the presence of a specific antecedent stimulus (SD) than in its absence, due to a history of differential reinforcement.',
    example: 'A child who asks for juice only when juice is visible has learned a discriminated operant under the control of the visible juice.',
  },
  {
    id: 'b92',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Punisher',
    definition: 'A stimulus whose presentation following a behavior decreases the future frequency of that behavior under similar conditions.',
    example: 'A reprimand that decreases a student\'s talking out of turn functions as a punisher.',
  },
  {
    id: 'b93',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Environment',
    definition: 'The total constellation of external and internal stimuli that can influence an organism\'s behavior at any given moment.',
    example: 'The physical setting, the presence of other people, and the organism\'s internal physiological state all constitute parts of the environment.',
  },
  {
    id: 'b94',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Reflex',
    definition: 'An unlearned, automatic stimulus-response relationship in which a specific stimulus reliably elicits a specific response without prior conditioning.',
    example: 'The knee-jerk response to a tap on the patellar tendon is a reflex.',
  },
  {
    id: 'b95',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'ABC Recording',
    definition: 'A direct observation method in which the observer records the antecedent, behavior, and consequence for each occurrence of a target behavior in sequence.',
    example: 'A teacher records that a student\'s hitting (B) was preceded by a peer taking a toy (A) and followed by the peer crying and returning the toy (C).',
  },
  {
    id: 'b96',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Anecdotal Observation',
    definition: 'A narrative, non-systematic method of recording behavior in which the observer writes a running account of events as they occur, without predetermined categories.',
    example: 'A teacher writes "Marcus became upset during math and threw his pencil" as an anecdotal observation.',
  },
  {
    id: 'b99',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Habilitation',
    definition: 'The process of teaching new skills and behaviors that enable a person to function more effectively and independently in their environment.',
    example: 'Teaching a young child with autism to communicate using PECS is a habilitation goal.',
  },
  {
    id: 'b100',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Behavioral Assessment',
    definition: 'A systematic process of gathering information about a person\'s behavior and the environmental variables that influence it, used to guide intervention planning.',
    example: 'A BCBA conducts a behavioral assessment including interviews, direct observation, and preference assessments before designing a behavior intervention plan.',
  },
  {
    id: 'b102',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Target Behavior',
    definition: 'The specific behavior selected for measurement and change in a behavior analysis program; defined in observable and measurable terms.',
    example: 'The target behavior "will independently request a preferred item using a complete sentence" is defined in observable and measurable terms.',
  },
  {
    id: 'b103',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Behavioral Cusp',
    definition: 'A behavior change that has consequences beyond the change itself, opening access to new reinforcers, contingencies, and environments.',
    example: 'Learning to read is a behavioral cusp because it opens access to an enormous range of new learning opportunities and reinforcers.',
  },
  {
    id: 'b104',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Pivotal Behavior',
    definition: 'A behavior that, when changed, produces widespread collateral improvements in other behaviors that were not directly targeted for intervention.',
    example: 'Increasing a child\'s motivation to engage with the environment is a pivotal behavior because it produces improvements across multiple skill areas.',
  },
  {
    id: 'b105',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Positive Reinforcer',
    definition: 'A stimulus whose presentation following a behavior increases the future frequency of that behavior under similar conditions.',
    example: 'A token delivered after each correct math problem functions as a positive reinforcer if problem-solving frequency increases.',
  },
  {
    id: 'b106',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Premack Principle',
    definition: 'The principle that a higher-probability behavior can be used to reinforce a lower-probability behavior; access to a preferred activity contingent on completing a less preferred activity.',
    example: 'Allowing a child to play video games (high-probability behavior) contingent on completing homework (low-probability behavior) applies the Premack Principle.',
  },
  {
    id: 'b107',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Generalized Conditioned Reinforcer',
    definition: 'A conditioned reinforcer that has been paired with many other reinforcers and therefore maintains its reinforcing value across a wide range of motivating operations.',
    example: 'Money is a generalized conditioned reinforcer because it can be exchanged for many different primary and conditioned reinforcers.',
  },
  {
    id: 'b108',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Reinforcer Assessment',
    definition: 'A systematic procedure for identifying stimuli that function as reinforcers for a specific individual under current motivating conditions.',
    example: 'A BCBA conducts a paired-stimulus preference assessment and then tests whether high-preference items function as reinforcers by measuring their effect on behavior.',
  },
  {
    id: 'b111',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Avoidance Contingency',
    definition: 'A negative reinforcement contingency in which a behavior prevents the onset of an aversive stimulus that has not yet occurred.',
    example: 'A student completes homework to avoid the aversive experience of receiving a failing grade.',
  },
  {
    id: 'b112',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Escape Contingency',
    definition: 'A negative reinforcement contingency in which a behavior terminates or reduces an aversive stimulus that is already present.',
    example: 'A child cries during a difficult task and the task is removed; the removal of the task negatively reinforces crying via an escape contingency.',
  },
  {
    id: 'b113',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Conditioned Negative Reinforcer',
    definition: 'A previously neutral stimulus that has acquired the ability to function as a negative reinforcer through pairing with an unconditioned or other conditioned aversive stimulus.',
    example: 'A warning tone that signals an impending shock becomes a conditioned negative reinforcer; behaviors that terminate the tone are negatively reinforced.',
  },
  {
    id: 'b114',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Free-Operant Avoidance',
    definition: 'An avoidance contingency in which the organism can respond at any time to postpone or prevent an aversive stimulus, with no discrete trials or warning signals.',
    example: 'A rat in a Sidman avoidance procedure can press a lever at any time to reset a shock timer, with no warning stimulus.',
  },
  {
    id: 'b115',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Unconditioned Negative Reinforcer',
    definition: 'A stimulus whose removal or reduction increases the future frequency of behavior without prior conditioning; an aversive stimulus by phylogenetic history.',
    example: 'Extreme heat is an unconditioned negative reinforcer; behaviors that reduce heat exposure are negatively reinforced without any prior learning.',
  },
  {
    id: 'b116',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Discriminated Avoidance',
    definition: 'An avoidance contingency in which a warning signal (CS) precedes the aversive stimulus (US), and behavior that occurs during the warning signal prevents the US.',
    example: 'A driver slows down when they see a speed limit sign (warning signal) to avoid a speeding ticket (aversive stimulus).',
  },
  {
    id: 'b117',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Adjunctive Behaviors',
    definition: 'Behaviors that emerge as a by-product of intermittent reinforcement schedules, occurring at high rates during the interval between reinforcement opportunities.',
    example: 'Excessive drinking in animals on fixed-interval schedules is an adjunctive behavior that emerges without direct reinforcement.',
  },
  {
    id: 'b118',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Alternative Schedule (Alt)',
    definition: 'A compound schedule in which reinforcement is delivered for the first response after either a fixed/variable interval or a fixed/variable ratio requirement is met, whichever occurs first.',
    example: 'An Alt FR10 VI60s schedule delivers reinforcement after 10 responses OR after 60 seconds, whichever comes first.',
  },
  {
    id: 'b119',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Differential Reinforcement of Low Rates (DRL)',
    definition: 'A schedule in which reinforcement is delivered only when a behavior occurs at or below a specified rate or after a minimum inter-response time has elapsed.',
    example: 'A DRL 5-minute schedule delivers reinforcement only if the student waits at least 5 minutes between requests.',
  },
  {
    id: 'b120',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Behavioral Contrast',
    definition: 'An increase in response rate in one component of a multiple schedule when reinforcement is reduced or removed in the other component.',
    example: 'When a child\'s disruptive behavior is placed on extinction in the classroom, it may temporarily increase at home — an example of behavioral contrast.',
  },
  {
    id: 'b122',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Compound Schedule of Reinforcement',
    definition: 'A schedule that combines two or more simple schedules of reinforcement, either simultaneously or sequentially, to govern when reinforcement is delivered.',
    example: 'A multiple schedule that alternates between FR10 and extinction components is a compound schedule.',
  },
  {
    id: 'b123',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Conjunctive Schedule (Conj)',
    definition: 'A compound schedule in which both a ratio and an interval requirement must be satisfied before reinforcement is delivered.',
    example: 'A Conj FR5 FI60s schedule requires both 5 responses AND 60 seconds to have elapsed before reinforcement is available.',
  },
  {
    id: 'b125',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Differential Reinforcement of Diminishing Rates (DRD)',
    definition: 'A schedule in which reinforcement is delivered at the end of an interval only if the number of responses during that interval is less than or equal to a decreasing criterion.',
    example: 'A DRD schedule is used to gradually reduce a student\'s hand-raising from 20 times per hour to 5 times per hour.',
  },
  {
    id: 'b126',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Differential Reinforcement of High Rates (DRH)',
    definition: 'A schedule in which reinforcement is delivered only when the rate of responding meets or exceeds a specified minimum criterion.',
    example: 'A DRH schedule is used to increase a student\'s reading fluency by reinforcing only when they read at least 100 words per minute.',
  },
  {
    id: 'b127',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Lag Schedule',
    definition: 'A reinforcement schedule in which a response is reinforced only if it is different from the previous n responses, used to increase behavioral variability.',
    example: 'A Lag 1 schedule reinforces a child\'s play behavior only when it differs from the immediately preceding play behavior, increasing variety.',
  },
  {
    id: 'b129',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Progressive Schedule of Reinforcement',
    definition: 'A schedule in which the response requirement or time interval systematically increases (or decreases) across successive reinforcement deliveries.',
    example: 'A progressive-ratio schedule that doubles the ratio requirement after each reinforcer delivery is used to assess the reinforcing value of a stimulus.',
  },
  {
    id: 'b131',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Ratio Strain',
    definition: 'A disruption in responding characterized by pausing, emotional behavior, and eventual cessation that occurs when a ratio schedule is increased too rapidly.',
    example: 'A student who was on FR5 and is abruptly shifted to FR100 may show ratio strain, with long pauses and eventual refusal to respond.',
  },
  {
    id: 'b132',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Schedule of Reinforcement',
    definition: 'The rule that specifies which occurrences of a behavior will be followed by a reinforcer; describes the relationship between responding and reinforcement delivery.',
    example: 'A fixed-ratio 10 schedule of reinforcement delivers a reinforcer after every 10th response.',
  },
  {
    id: 'b133',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Limited Hold',
    definition: 'An added contingency specifying that reinforcement is available only for a limited time after the schedule requirement is met; responses after the window closes do not produce reinforcement.',
    example: 'An FI 60s LH 10s schedule means the reinforcer is available only during the 10-second window after the 60-second interval has elapsed.',
  },
  {
    id: 'b134',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Schedule Thinning',
    definition: 'The systematic process of gradually increasing the response requirement or time interval between reinforcements to shift from a dense to a leaner schedule.',
    example: 'A BCBA thins a CRF schedule to VR10 over several weeks to maintain behavior with less frequent reinforcement.',
  },
  {
    id: 'b136',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Response Blocking',
    definition: 'A punishment procedure in which the practitioner physically prevents the completion of a problem behavior, typically used to interrupt self-injurious or stereotypic behavior.',
    example: 'A therapist gently holds a client\'s hands down when they attempt to hit their head, blocking the completion of the self-injurious response.',
  },
  {
    id: 'b137',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Positive Practice Overcorrection',
    definition: 'A punishment procedure requiring the individual to repeatedly practice the correct form of the behavior contingent on each occurrence of the problem behavior.',
    example: 'After a student writes on the desk, they are required to practice writing on paper 20 times as positive practice overcorrection.',
  },
  {
    id: 'b138',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Response Interruption and Redirection (RIRD)',
    definition: 'A procedure in which stereotypic or problem behavior is interrupted and the individual is prompted to engage in an alternative, incompatible behavior.',
    example: 'When a child begins to vocally stim, the therapist interrupts by saying "hands down" and redirects the child to a functional communication response.',
  },
  {
    id: 'b139',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Discriminative Stimulus for Punishment (S^P)',
    definition: 'A stimulus in the presence of which a behavior has been punished and whose presence therefore suppresses that behavior.',
    example: 'A student who has been reprimanded for talking in class only when the principal is present may suppress talking in the principal\'s presence — the principal functions as an S^P.',
  },
  {
    id: 'b140',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Restitutional Overcorrection',
    definition: 'A punishment procedure requiring the individual to restore the environment to a state better than it was before the problem behavior occurred.',
    example: 'After a student knocks items off a shelf, they are required to pick up those items AND straighten all other items on the shelf.',
  },
  {
    id: 'b141',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Recovery from Punishment',
    definition: 'The return of a suppressed behavior to near-baseline levels after punishment is discontinued, analogous to spontaneous recovery after extinction.',
    example: 'A child\'s hitting that was suppressed by time-out may recover to near-baseline levels after time-out is no longer implemented.',
  },
  {
    id: 'b142',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Bonus Response Cost',
    definition: 'A response cost variation in which the individual begins a session with bonus tokens beyond the minimum needed, and tokens are removed contingent on problem behavior.',
    example: 'A student begins class with 5 bonus tokens and loses one token each time they call out without raising their hand.',
  },
  {
    id: 'b143',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Nonexclusion Time-Out',
    definition: 'A time-out procedure in which the individual remains in the environment but is denied access to reinforcement for a specified period contingent on problem behavior.',
    example: 'A student who engages in disruptive behavior is moved to a chair at the edge of the classroom where they can observe but not participate in the activity.',
  },
  {
    id: 'b144',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Contingent Observation',
    definition: 'A mild nonexclusion time-out procedure in which the individual is moved to the periphery of the activity to observe peers engaging in the activity without being able to participate.',
    example: 'A child who hits during a game is moved to sit and watch the game for 2 minutes before returning to play.',
  },
  {
    id: 'b145',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Partition Time-Out',
    definition: 'A nonexclusion time-out procedure in which a screen or partition is placed between the individual and the reinforcing environment, blocking access to reinforcement without removing the individual from the room.',
    example: 'A screen is placed in front of a student who engages in disruptive behavior, blocking their view of the classroom activity.',
  },
  {
    id: 'b146',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Exclusion Time-Out',
    definition: 'A time-out procedure in which the individual is physically removed from the reinforcing environment to a less reinforcing area contingent on problem behavior.',
    example: 'A student who engages in aggression is escorted to a quiet room adjacent to the classroom for a 5-minute time-out.',
  },
  {
    id: 'b147',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Time-Out from Positive Reinforcement',
    definition: 'A negative punishment procedure in which access to sources of positive reinforcement is contingently removed for a specified period following problem behavior.',
    example: 'Removing a child from a preferred activity for 3 minutes contingent on hitting is a time-out from positive reinforcement procedure.',
  },
  {
    id: 'b148',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Response Cost',
    definition: 'A negative punishment procedure in which a specified amount of a reinforcer is contingently removed following each occurrence of problem behavior.',
    example: 'Removing 5 minutes of free time each time a student is off-task is a response cost procedure.',
  },
  {
    id: 'b149',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Planned Ignoring',
    definition: 'A mild negative punishment procedure in which all social attention is withheld contingent on problem behavior; effective only when social attention is the maintaining reinforcer.',
    example: 'A teacher turns away and provides no attention when a student whines, using planned ignoring to reduce attention-maintained whining.',
  },
  {
    id: 'b150',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Abative Effect',
    definition: 'The effect of an abolishing operation that decreases the current reinforcing value of a stimulus and decreases the current frequency of behavior that has been reinforced by that stimulus.',
    example: 'Satiation with food has an abative effect: it decreases the reinforcing value of food and decreases food-seeking behavior.',
  },
  {
    id: 'b151',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Behavior-Altering Effect',
    definition: 'The effect of a motivating operation on the current frequency of behavior; includes the evocative effect (increases behavior) and the abative effect (decreases behavior).',
    example: 'Food deprivation has a behavior-altering effect: it increases food-seeking behavior (evocative effect) and increases the reinforcing value of food (value-altering effect).',
  },
  {
    id: 'b152',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Reflexive Conditioned Motivating Operation (CMO-R)',
    definition: 'A conditioned motivating operation that has acquired its MO properties by being paired with worsening conditions; its presence signals that conditions are about to worsen.',
    example: 'A warning tone that reliably precedes an aversive event functions as a CMO-R: its presence evokes escape behavior and increases the reinforcing value of escape.',
  },
  {
    id: 'b153',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Conditioned Motivating Operation (CMO)',
    definition: 'A motivating operation whose value-altering and behavior-altering effects are the result of learning; acquired through experience rather than phylogeny.',
    example: 'A locked door becomes a CMO for key-seeking behavior because a history of learning has established the locked door as a signal that access is restricted.',
  },  {
    id: 'b156',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Surrogate Conditioned Motivating Operation (CMO-S)',
    definition: 'A conditioned motivating operation that has acquired its MO properties by being paired with an unconditioned motivating operation; it mimics the effects of the UMO it was paired with.',
    example: 'A specific room where a child has experienced pain may function as a CMO-S, evoking escape behavior and increasing the reinforcing value of escape even without pain present.',
  },
  {
    id: 'b157',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Value-Altering Effect',
    definition: 'The effect of a motivating operation on the reinforcing or punishing effectiveness of a stimulus; either increases (establishing) or decreases (abolishing) the current value of the stimulus.',
    example: 'Food deprivation has a value-altering effect by increasing the reinforcing value of food; satiation has the opposite value-altering effect.',
  },
  {
    id: 'b158',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Evocative Effect',
    definition: 'The behavior-altering effect of an establishing operation that increases the current frequency of behavior that has been reinforced by the relevant stimulus.',
    example: 'Food deprivation has an evocative effect: it increases the current frequency of food-seeking and food-requesting behavior.',
  },
  {
    id: 'b160',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Transitive Conditioned Motivating Operation (CMO-T)',
    definition: 'A conditioned motivating operation that establishes the reinforcing value of a stimulus that is needed to obtain another reinforcer; it makes an instrumental stimulus valuable.',
    example: 'A locked door functions as a CMO-T for key-seeking behavior: the locked door establishes the key as a reinforcer because the key is needed to access the room.',
  },
  {
    id: 'b161',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Unconditioned Motivating Operation (UMO)',
    definition: 'A motivating operation whose value-altering and behavior-altering effects are unlearned; effective without prior conditioning due to phylogenetic history.',
    example: 'Food deprivation, water deprivation, and extreme temperature are unconditioned motivating operations.',
  },
  {
    id: 'b163',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Antecedent Stimulus Class',
    definition: 'A group of stimuli that all evoke the same operant behavior because they share a history of differential reinforcement.',
    example: 'All instances of the letter "A" — regardless of font, size, or color — form an antecedent stimulus class because they all evoke the same reading response.',
  },
  {
    id: 'b165',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Stimulus Delta (SΔ)',
    definition: 'A stimulus in the presence of which a behavior has not been reinforced and therefore occurs at a lower rate; signals that reinforcement is not available.',
    example: 'A red light at a crosswalk is an SΔ for crossing because crossing during a red light has not been reinforced (and has been punished).',
  },
  {
    id: 'b167',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Arbitrary Stimulus Class',
    definition: 'A group of stimuli that control the same response but share no common physical features; membership in the class is defined by the organism\'s learning history.',
    example: 'The spoken word "dog," a picture of a dog, and a toy dog form an arbitrary stimulus class because they share no physical features but all evoke the same tact response.',
  },
  {
    id: 'b169',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Concept',
    definition: 'A stimulus class defined by a common property or set of properties; responding to all members of the class and not to non-members constitutes concept formation.',
    example: 'A child who correctly identifies all red objects as "red" and no non-red objects as "red" has formed the concept of redness.',
  },
  {
    id: 'b170',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Overselective Stimulus Control',
    definition: 'A pattern in which behavior comes under the control of only a subset of the relevant stimulus features, leading to failure to respond to the full stimulus complex.',
    example: 'A child who only responds to the word "sit" when it is spoken by their therapist (but not by other people) shows overselective stimulus control.',
  },
  {
    id: 'b171',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Stimulus Discrimination Training',
    definition: 'A procedure that produces differential responding to two or more stimuli by reinforcing responding in the presence of the SD and withholding reinforcement in the presence of the SΔ.',
    example: 'A therapist reinforces a child for touching the red card and withholds reinforcement for touching the blue card, conducting stimulus discrimination training.',
  },
  {
    id: 'b172',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Conditional Discrimination',
    definition: 'A discrimination in which the correct response to a comparison stimulus depends on the value of a sample or contextual stimulus; the SD changes depending on the context.',
    example: 'A child must touch the circle when the sample is red and touch the square when the sample is blue — the correct response is conditional on the sample.',
  },
  {
    id: 'b173',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Overshadowing',
    definition: 'A stimulus control phenomenon in which a more salient stimulus in a compound stimulus prevents a less salient stimulus from acquiring stimulus control.',
    example: 'If a loud tone and a dim light are presented together as a compound CS, the tone may overshadow the light, preventing the light from acquiring conditioned eliciting properties.',
  },
  {
    id: 'b174',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Stimulus Fading',
    definition: 'A procedure for transferring stimulus control in which the properties of the SD are gradually changed while the learner continues to respond correctly.',
    example: 'A therapist fades a written prompt from bold black text to light gray to invisible while the student continues to read the word correctly.',
  },
  {
    id: 'b175',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Constant Time Delay',
    definition: 'A prompting procedure in which a fixed interval (e.g., 4 seconds) is always inserted between the SD and the prompt, giving the learner an opportunity to respond before the prompt is delivered.',
    example: 'A therapist says "What is this?" and waits exactly 4 seconds before pointing to the correct picture, using constant time delay.',
  },
  {
    id: 'b176',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Progressive Time Delay',
    definition: 'A prompting procedure in which the interval between the SD and the prompt is gradually increased across trials, giving the learner increasing opportunity to respond independently.',
    example: 'A therapist begins with a 0-second delay (simultaneous prompting) and increases the delay by 1 second per session until reaching a 5-second delay.',
  },
  {
    id: 'b178',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Stimulus Generalization Gradient',
    definition: 'A graphic representation showing the relationship between the degree of similarity of a stimulus to the original SD and the rate of responding to that stimulus.',
    example: 'A pigeon trained to peck at a 550nm light shows a stimulus generalization gradient: highest responding at 550nm and decreasing responding as wavelength deviates from 550nm.',
  },
  {
    id: 'b179',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Stimulus Blocking',
    definition: 'A stimulus control phenomenon in which prior conditioning to one stimulus prevents a second stimulus from acquiring stimulus control when both are presented together.',
    example: 'If a tone has already been conditioned as a CS, pairing a light with the tone and the US may not condition the light because the tone blocks the light from acquiring CS properties.',
  },
  {
    id: 'b181',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Feature Stimulus Class',
    definition: 'A group of stimuli that share one or more common physical features (topography, size, color, function) and therefore evoke the same response.',
    example: 'All round objects form a feature stimulus class because they share the physical feature of roundness.',
  },
  {
    id: 'b182',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Time Delay',
    definition: 'A prompting procedure in which a brief interval is inserted between the presentation of the SD and the delivery of the prompt, allowing the learner an opportunity to respond independently.',
    example: 'A therapist presents a picture card and waits 3 seconds before providing a verbal prompt, using time delay to promote independent responding.',
  },
  {
    id: 'b184',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Speaker',
    definition: 'In Skinner\'s analysis of verbal behavior, the organism whose verbal behavior is shaped and maintained by a verbal community.',
    example: 'A child who has learned to say "cookie" to request a cookie is functioning as a speaker in a verbal episode.',
  },
  {
    id: 'b186',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Bidirectional Naming',
    definition: 'A higher-order operant in which an organism can both tact (name) and respond to the names of stimuli after observing a single naming event, without direct reinforcement of both functions.',
    example: 'A child who observes a teacher naming a new object can then both tact the object and respond to its name without additional training — demonstrating bidirectional naming.',
  },
  {
    id: 'b194',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Verbal Behavior',
    definition: 'Behavior that is reinforced through the mediation of another person who has been trained by the verbal community; behavior whose consequences are socially mediated.',
    example: 'Saying "water" to obtain water from a caregiver is verbal behavior because its reinforcement is mediated by another person.',
  },  {
    id: 'b196',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Elementary Verbal Operants',
    definition: 'The basic functional units of verbal behavior identified by Skinner: mand, tact, echoic, intraverbal, textual, transcription, and copying text.',
    example: 'A BCBA assesses all elementary verbal operants to determine which are present and which require intervention.',
  },
  {
    id: 'b202',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Class Expansion',
    definition: 'The addition of new stimuli to an existing equivalence class through training, so that the new stimuli acquire all the functions of the existing class members.',
    example: 'After establishing an equivalence class for "dog" (spoken word, picture, written word), adding the sign for "dog" expands the class.',
  },
  {
    id: 'b205',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Class Merger',
    definition: 'The combination of two previously separate equivalence classes into a single larger class when a common element is added that is a member of both classes.',
    example: 'If class 1 contains {A1, B1, C1} and class 2 contains {A2, B2, C2}, adding a stimulus D that is trained as equivalent to both C1 and A2 merges the two classes.',
  },
  {
    id: 'b207',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Class-Specific Reinforcement',
    definition: 'A procedure in which reinforcement is delivered for correct responses to one equivalence class but not another, used to establish or test class membership.',
    example: 'Reinforcing responses to class A stimuli but not class B stimuli is class-specific reinforcement.',
  },
  {
    id: 'b215',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Simple Discrimination',
    definition: 'A discrimination in which responding to one stimulus is reinforced and responding to another stimulus is not reinforced, without the correct response depending on a contextual stimulus.',
    example: 'A child who touches the red card and not the blue card has learned a simple discrimination.',
  },
  {
    id: 'b219',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Deictic Relations',
    definition: 'Relational frames that involve perspective-taking and are defined relative to the speaker\'s point of view; includes I/you, here/there, and now/then.',
    example: 'Understanding that "I" refers to the speaker and "you" refers to the listener requires learning deictic relations.',
  },
  {
    id: 'b220',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Arbitrarily Applicable Relational Responding',
    definition: 'The ability to respond to stimuli in terms of derived relations that are not based on the physical properties of the stimuli but on contextual cues.',
    example: 'Responding to a coin as "more valuable" than a larger rock because of learned social conventions is arbitrarily applicable relational responding.',
  },
  {
    id: 'b221',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Derived Relations',
    definition: 'Stimulus relations that emerge without direct training as a result of relational framing; broader than equivalence, including relations such as more/less, before/after, and part/whole.',
    example: 'After learning that A is larger than B and B is larger than C, deriving that A is larger than C without direct training is a derived relation.',
  },
  {
    id: 'b230',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Causal Relations',
    definition: 'Relational frames in which one event is responded to as causing another; includes if/then and because relations.',
    example: 'Understanding that "if it rains, the ground gets wet" involves causal relational framing.',
  },
  {
    id: 'b231',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Mutual Entailment',
    definition: 'A property of relational framing in which if A is related to B in a given way, then B is related to A in a derived way; the bidirectional nature of relational frames.',
    example: 'If A is trained as "same as" B (mutual entailment), then B is also "same as" A without direct training.',
  },
  {
    id: 'b234',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Nonequivalence Relations',
    definition: 'Relational frames other than equivalence, including comparison (more/less), opposition (opposite), hierarchy (part/whole), and temporal (before/after) relations.',
    example: 'Responding to 10 as "more than" 5 involves a nonequivalence comparison relation.',
  },
  {
    id: 'b236',
    domain: 'B', domainFull: 'Concepts & Principles',
    term: 'Combinatorial Entailment',
    definition: 'A property of relational framing in which if A is related to B and B is related to C, then A is related to C and C is related to A in derived ways.',
    example: 'If A is trained as "same as" B and B is trained as "same as" C, combinatorial entailment produces the derived relations A-C and C-A.',
  },
  { id: 'rr-fc-behavioral-momentum-high-p-request-sequence', term: 'Behavioral Momentum  -  High-p Request Sequence', definition: 'The clinical application of behavioral momentum: a series of high-probability (high-p) requests are delivered and reinforced before a low-probability (low-p) request, increasing the likelihood of compliance with the low-p request (G.1). The principle (B.22) and the clinical procedure (G.1) are related but distinct concepts.', domain: 'B', domainFull: 'Concepts & Principles', example: 'Before asking a student to complete a non-preferred math worksheet (low-p request), a teacher delivers three quick high-probability requests (\'touch your nose,\' \'clap your hands,\' \'stand up\') — using behavioral momentum to increase compliance with the difficult request.' },
  { id: 'rr-fc-celeration', term: 'Celeration', definition: 'A measure of how behavior frequency changes over time, expressed as a multiplicative rate of change per unit of time on a Standard Celeration Chart (e.g., ×2 per week).', domain: 'B', domainFull: 'Concepts & Principles', example: 'A student\'s rate of correct reading responses increases from 20 per minute to 40 per minute over two weeks on the Standard Celeration Chart — the celeration (rate of change in rate) is x2.0, indicating the behavior doubled in frequency.' },
  { id: 'rr-fc-comparative-analysis', term: 'Comparative Analysis', definition: 'A research strategy that compares the effects of two or more complete treatment packages to determine which is more effective.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA conducts a component analysis comparing the effects of DRO alone, FCT alone, and their combination on problem behavior — a comparative analysis that identifies which treatment component or combination is most effective.' },
  { id: 'rr-fc-component-analysis', term: 'Component Analysis', definition: 'A research strategy that systematically removes or adds components of a treatment package to identify which components are necessary and sufficient for behavior change.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA evaluates a treatment package (DRO + FCT + extinction) by systematically removing one component at a time to determine which components are necessary for behavior reduction — using a component analysis to identify active ingredients.' },
  { id: 'rr-fc-concept-formation', term: 'Concept Formation', definition: 'The development of stimulus control by a common property shared by a class of stimuli, such that the behavior occurs in the presence of all members of the class and not in the presence of non-members.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child learns to label all four-legged animals as \'dog\' regardless of breed, size, or color — demonstrating concept formation by responding to the common feature (four legs, fur) across a class of stimuli.' },
  { id: 'rr-fc-contingent-exercise', term: 'Contingent Exercise', definition: 'A form of positive punishment in which the learner is required to engage in physical exercise contingent on the occurrence of a target behavior.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A student who engages in out-of-seat behavior is required to do 10 jumping jacks contingent on each instance — using contingent exercise as a reductive procedure based on the assumption that the exercise is mildly aversive.' },
  { id: 'rr-fc-cultural-responsiveness', term: 'Cultural Responsiveness', definition: 'The practice of adapting assessment and intervention procedures to be consistent with the cultural values, norms, and preferences of the client and their family.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA modifies a social skills curriculum to incorporate culturally relevant examples and consults with the family about culturally appropriate behavioral expectations before implementing the program — demonstrating cultural responsiveness.' },
  { id: 'rr-fc-cultural-variables-in-assessment', term: 'Cultural Variables in Assessment', definition: 'Factors related to a client\'s cultural background, language, values, and community norms that must be identified and integrated into the assessment process to ensure culturally responsive services.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA considers that a child\'s limited eye contact during assessment may reflect a cultural norm rather than a skill deficit, and consults with the family before interpreting the behavior as a target for intervention.' },
  { id: 'rr-fc-data-overlap', term: 'Data Overlap', definition: 'The proportion of data points in one phase that fall within the range of data points in an adjacent phase; high overlap weakens the evidence for a functional relationship.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA examines a multiple baseline graph and finds that 60% of intervention data points overlap with the range of baseline data — the high overlap indicates a weak treatment effect and reduces confidence in the intervention\'s effectiveness.' },
  { id: 'rr-fc-data-based-decision-making', term: 'Data-Based Decision Making', definition: 'The practice of using objective data collected on client behavior to guide decisions about continuing, modifying, or discontinuing an intervention.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA reviews a student\'s weekly data trend and, noting that the behavior has not decreased after three weeks of intervention, modifies the treatment plan rather than continuing an ineffective procedure — using data to guide clinical decisions.' },
  { id: 'rr-fc-derived-relational-responding', term: 'Derived Relational Responding', definition: 'Responding to relations among stimuli based on a history of reinforcement for relational responding, rather than based on the physical properties of the stimuli.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A child learns that A=B and B=C through direct training; without additional training, the child responds as if A=C (transitivity) and C=A (symmetry) — demonstrating derived relational responding that emerges from the trained relations.' },
  { id: 'rr-fc-differential-reinforcement', term: 'Differential Reinforcement', definition: 'A procedure in which reinforcement is provided for responses that meet a specified criterion and withheld for responses that do not meet that criterion.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA reinforces appropriate requests for attention while withholding reinforcement for screaming — using differential reinforcement to increase the appropriate behavior and decrease the inappropriate behavior through selective delivery of consequences.' },
  { id: 'rr-fc-direct-measure', term: 'Direct Measure', definition: 'A measurement procedure in which the behavior of interest is observed and recorded as it occurs, without relying on reports from others or permanent products.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A behavior technician counts the number of times a student hits a peer during a 30-minute session using event recording — a direct measure because the behavior itself (hitting) is being observed and recorded as it occurs.' },
  { id: 'rr-fc-discrete-trial-teaching-dtt', term: 'Discrete Trial Teaching (DTT)', definition: 'A structured teaching format consisting of a discriminative stimulus, a learner response, and a consequence, with a clear beginning and end to each trial and an intertrial interval.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA teaches a student to identify colors using DTT: the therapist presents a red card (discriminative stimulus), the student says \'red\' (response), and the therapist delivers a token (consequence), followed by a brief inter-trial interval before the next trial.' },
  { id: 'rr-fc-indirect-measure', term: 'Indirect Measure', definition: 'A measurement procedure that relies on reports, ratings, or recollections of behavior rather than direct observation of the behavior as it occurs.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA uses a rating scale completed by a teacher to estimate the frequency of a student\'s disruptive behavior — an indirect measure because the behavior is not directly observed; the teacher\'s recollection is used instead.' },
  { id: 'rr-fc-listener-responding', term: 'Listener Responding', definition: 'Nonverbal behavior under the control of verbal stimuli produced by another person; the listener\'s behavior is reinforced by the verbal community.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A student correctly points to the picture of a dog when the therapist says \'dog\' — demonstrating listener responding (a receptive language skill) in which the student\'s behavior is controlled by the verbal behavior of another person.' },
  { id: 'rr-fc-mand-training', term: 'Mand Training', definition: 'A procedure for teaching mands by establishing motivating operations for specific reinforcers, then prompting and reinforcing requests for those reinforcers.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA establishes an establishing operation (EO) for a preferred item by withholding it, then prompts the child to say \'cookie\' and immediately delivers the cookie contingent on the mand — teaching the child to request using a mand.' },
  { id: 'rr-fc-non-contingent-reinforcement-ncr', term: 'Non-Contingent Reinforcement (NCR)', definition: 'Delivery of a reinforcer on a fixed-time or variable-time schedule, independent of the occurrence of any specific behavior; used to reduce problem behavior maintained by that reinforcer.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA delivers attention to a student on a fixed-time 3-minute schedule regardless of the student\'s behavior — using NCR to reduce the motivation for attention-maintained problem behavior by providing attention non-contingently.' },
  { id: 'rr-fc-post-reinforcement-pause', term: 'Post-Reinforcement Pause', definition: 'A pause in responding that occurs immediately after the delivery of a reinforcer, most commonly observed in fixed-ratio and fixed-interval schedules.', domain: 'B', domainFull: 'Concepts & Principles', example: 'After earning a reinforcer on an FR 20 schedule, a student pauses for 30 seconds before beginning the next ratio — demonstrating the post-reinforcement pause that is characteristic of fixed-ratio schedules.' },
  { id: 'rr-fc-prediction-baseline-logic', term: 'Prediction (Baseline Logic)', definition: 'The first element of baseline logic: the stable baseline data allow prediction of the future course of behavior if the intervention were not introduced.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA collects stable baseline data showing that a student averages 12 problem behaviors per session; this stable baseline allows the prediction that the behavior would continue at approximately 12 per session if no intervention were introduced.' },
  { id: 'rr-fc-prompt-delay', term: 'Prompt Delay', definition: 'A fading procedure in which a time delay is inserted between the discriminative stimulus and the delivery of a prompt, allowing the learner to respond independently before the prompt is given.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA presents a discriminative stimulus and waits 4 seconds before delivering a prompt, giving the student an opportunity to respond independently — using a constant prompt delay procedure to fade prompts and promote independent responding.' },
  { id: 'rr-fc-punishment', term: 'Punishment', definition: 'A process in which a consequence follows a behavior and decreases the future frequency of that behavior.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A student\'s hand-raising behavior decreases after the teacher begins calling on the student and requiring a lengthy explanation every time the student raises their hand — the consequence (lengthy explanation) functions as punishment because it decreases the behavior.' },
  { id: 'rr-fc-reactivity', term: 'Reactivity', definition: 'A change in the target behavior that occurs because the individual is aware of being observed, which may cause the data to not accurately represent typical performance.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A student\'s disruptive behavior decreases when a behavior technician begins recording data during sessions — the change in behavior due to being observed (reactivity) may lead to an underestimate of the true baseline rate of the behavior.' },
  { id: 'rr-fc-reinforcement', term: 'Reinforcement', definition: 'A process in which a consequence follows a behavior and increases the future frequency of that behavior.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A student begins raising their hand more frequently after the teacher consistently calls on them when they raise their hand — the teacher\'s attention functions as a reinforcer because it increases the future probability of hand-raising.' },
  { id: 'rr-fc-satiation', term: 'Satiation', definition: 'A decrease in the reinforcing effectiveness of a stimulus as a result of repeated exposure to or consumption of that stimulus.', domain: 'B', domainFull: 'Concepts & Principles', example: 'After a student has consumed a large meal, food no longer functions as an effective reinforcer for the remainder of the session — the student is satiated, and the motivating operation (food deprivation) that established food as a reinforcer is no longer present.' },
  { id: 'rr-fc-scallop', term: 'Scallop', definition: 'The characteristic cumulative record pattern produced by a fixed-interval schedule — a post-reinforcement pause followed by gradually accelerating responding as the interval end approaches.', domain: 'B', domainFull: 'Concepts & Principles', example: 'On a fixed-interval schedule, a student shows a characteristic pattern of low responding immediately after reinforcement delivery, with responding accelerating as the end of the interval approaches — producing the scallop pattern on a cumulative record.' },
  { id: 'rr-fc-socially-valid-goal', term: 'Socially Valid Goal', definition: 'An intervention goal that targets behaviors identified as meaningful and important by the client, caregivers, and the broader social community; goals should produce outcomes that matter in the client\'s natural environment.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA selects a goal of teaching a student to greet peers by name because the student\'s parents, teachers, and peers identified this as an important skill for social inclusion — a socially valid goal that is meaningful to the client\'s natural community.' },
  { id: 'rr-fc-standard-celeration-chart', term: 'Standard Celeration Chart', definition: 'A semi-logarithmic chart used to display behavior frequency over time, where the slope of the data path (celeration) represents the rate of change in behavior frequency.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA plots a student\'s daily reading fluency data on a Standard Celeration Chart and calculates a celeration of x1.3 per week — using the SCC to visualize the rate of behavior change and compare it to expected growth rates.' },
  { id: 'rr-fc-stimulus-overselectivity', term: 'Stimulus Overselectivity', definition: 'A phenomenon in which behavior comes under the control of only a subset of the relevant stimulus components in a complex stimulus, while other relevant components are ignored.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A student learns to identify a dog only when the dog has brown fur, failing to identify dogs of other colors — demonstrating stimulus overselectivity, in which responding is controlled by only a subset of the relevant stimulus features.' },
  { id: 'b-observational-learning', term: 'Observational Learning', definition: 'A process in which an observer\'s behavior changes as a result of observing a model\'s behavior and its consequences, without the observer directly experiencing those consequences; a form of vicarious learning in which the observer need not reproduce the model\'s exact topography.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A student who has never been reinforced for raising their hand begins raising their hand more frequently after observing a classmate receive praise for doing so — the observer\'s behavior changed through vicarious reinforcement without direct reinforcement of the observer.' },
  { id: 'rr-fc-verification-baseline-logic', term: 'Verification (Baseline Logic)', definition: 'The second element of baseline logic: the return to baseline (or a concurrent baseline) shows that behavior would not have changed without the intervention, ruling out extraneous variables.', domain: 'B', domainFull: 'Concepts & Principles', example: 'A BCBA uses an ABAB reversal design: behavior improves in the first B phase, returns to baseline levels in the second A phase, and improves again in the second B phase — the return to baseline levels (verification) confirms that the intervention caused the behavior change.' },
  { id: 'c1', term: 'Frequency / Count', definition: 'The number of times a behavior occurs during an observation period.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c2', term: 'Rate', definition: 'The number of responses per unit of time (frequency ÷ observation duration); allows comparison across sessions of different lengths.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c3', term: 'Duration', definition: 'The total amount of time a behavior lasts from onset to offset.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c4', term: 'Latency', definition: 'The elapsed time from the onset of a stimulus (SD or instruction) to the initiation of a response.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c5', term: 'Interresponse Time (IRT)', definition: 'The elapsed time between the offset of one response and the onset of the next response of the same type.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c7', term: 'Topography', definition: 'The physical form or shape of a behavior  -  what the behavior looks like.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c8', term: 'Continuous Measurement', definition: 'Measurement of every instance of a behavior during an observation period (e.g., event recording, duration recording).', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c9', term: 'Discontinuous Measurement', definition: 'Measurement of a sample of behavior during an observation period rather than every instance (e.g., interval recording, time sampling).', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c10', term: 'Whole Interval Recording', definition: 'A discontinuous measurement system in which the observer records whether the behavior occurred throughout the entire interval; tends to underestimate behavior.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c11', term: 'Partial Interval Recording', definition: 'A discontinuous measurement system in which the observer records whether the behavior occurred at any point during the interval; tends to overestimate behavior.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c12', term: 'Momentary Time Sampling (MTS)', definition: 'A discontinuous measurement system in which the observer records whether the behavior is occurring at the moment the interval ends; can over- or underestimate depending on behavior.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c13', term: 'Interobserver Agreement (IOA)', definition: 'The degree to which two or more independent observers record the same values for the same behavior during the same observation period; an index of measurement reliability.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c16', term: 'Cumulative Record', definition: 'A graph in which each data point represents the total number of responses emitted up to that point in time; the slope of the line represents rate of responding.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c17', term: 'Celeration Chart (Standard Celeration Chart)', definition: 'A semi-logarithmic chart used to display rate of behavior change (celeration) over time; allows comparison of behavior change across different behaviors and individuals.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c18', term: 'Permanent Product Recording', definition: 'A measurement method in which the tangible outcome or by-product of behavior is observed and recorded rather than the behavior itself; useful when the behavior leaves a lasting trace.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation', example: 'Counting the number of math problems completed correctly on a worksheet.' },
  { id: 'c20', term: 'Trial-by-Trial Data', definition: 'A recording method in which the response (correct, incorrect, prompted, no response) is recorded for each individual instructional trial; provides a detailed record of performance across opportunities.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c24', term: 'Bar Graph', definition: 'A data display format in which the height of each bar represents the value of a dependent variable for a given condition or category; used to compare discrete data points across conditions. Note: In ABA single-subject research, bar graphs are the standard tool for comparing conditions or phases. A histogram is a distinct format that displays frequency distributions of continuous data  -  the two terms are not interchangeable.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation', example: 'A bar graph comparing mean problem behavior rates across baseline, intervention, and maintenance phases.' },
  { id: 'c25', term: 'Visual Analysis', definition: 'The primary method of data interpretation in single-subject research; involves examining graphed data for level, trend, variability, immediacy of effect, overlap, and consistency across similar phases.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c26', term: 'Efficiency Measures (Trials to Criterion, Cost-Benefit)', definition: 'Measures of the resources required to produce a specified level of behavior change: (1) Trials to criterion  -  the number of learning opportunities required before a performance standard is met; (2) Cost-benefit analysis  -  a comparison of the resources expended (time, effort, materials) against the magnitude and social significance of the behavior change produced.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation', example: 'Procedure A achieves criterion in 20 trials; Procedure B achieves the same criterion in 50 trials. Procedure A is more efficient. A BCBA also considers whether the 30-trial savings justifies any difference in staff training cost.' },
  { id: 'c29', term: 'Measurement', definition: 'The process of assigning numbers or labels to objects or events according to a set of rules; in behavior analysis, the systematic observation and recording of the dimensional quantities of behavior over time.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A BCBA records the number of times a student raises their hand during a 30-minute class period, assigning a count to the behavior — an act of measurement that produces data for analysis.' },
  { id: 'c30', term: 'Repeatability', definition: 'The dimensional quantity of behavior reflecting the fact that a behavior can occur more than once; the basis for counting and rate measures; also called countability.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'Hand-raising has repeatability — it can occur once, twice, or many times within an observation period — making frequency and rate appropriate measures for this behavior.' },
  { id: 'c31', term: 'Temporal Extent', definition: 'The dimensional quantity of behavior reflecting the fact that every instance of behavior occupies some amount of time; the basis for duration measures.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A tantrum occupies time from its onset to its offset — this temporal extent makes duration an appropriate measure; a BCBA records that a tantrum lasted 4 minutes and 23 seconds.' },
  { id: 'c32', term: 'Temporal Locus', definition: 'The dimensional quantity of behavior reflecting the fact that every instance of behavior occurs at a specific point in time relative to other events; the basis for latency and inter-response time measures.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A student responds 8 seconds after the teacher delivers an instruction — the temporal locus of the response relative to the antecedent instruction is the basis for a latency measure.' },
  { id: 'c33', term: 'Magnitude', definition: 'The dimensional quantity of behavior reflecting the force or intensity of a response; measured in physical units such as decibels, pounds of pressure, or amplitude; less commonly measured in applied settings than frequency or duration.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A researcher measures the loudness of a client\'s vocalizations in decibels to quantify the magnitude of screaming behavior, tracking whether the intensity decreases following an intervention.' },
  { id: 'c36', term: 'Percentage', definition: 'The number of occurrences of a behavior divided by the total number of opportunities for that behavior to occur, multiplied by 100; appropriate when behavior is measured as a proportion of opportunities rather than as a rate.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A BCBA records that a student correctly identified 16 of 20 picture cards (80%) during a discrete trial session — percentage is appropriate because each trial is an opportunity and the number of trials varies.' },
  { id: 'c44', term: 'Planned Activity Check (PLACHECK)', definition: 'A group time sampling method in which an observer records the number or percentage of individuals in a group who are engaged in a specified behavior at the moment of observation; a form of momentary time sampling applied to groups.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'At the end of each 5-minute interval, a teacher scans the classroom and records how many of the 20 students are engaged in independent work — a PLACHECK that provides a group-level estimate of on-task behavior.' },
  { id: 'c46', term: 'Artifact', definition: 'A measurement outcome that does not accurately reflect the true value of the behavior being measured; a spurious data point produced by errors in the measurement process rather than by actual changes in behavior.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A data sheet shows zero instances of problem behavior during a session, but this is an artifact — the observer was absent for 10 minutes and missed the actual occurrences, so the zero does not reflect the true rate of behavior.' },
  { id: 'c47', term: 'Accuracy', definition: 'The extent to which observed values of a behavior match the true values; a measure of how closely the data collected by an observer reflect what actually occurred; requires a known standard or criterion against which to compare.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A BCBA compares a trainee\'s data against a video recording of the session — the trainee recorded 14 instances of the target behavior while the video shows 15, yielding an accuracy score of 93%.' },
  { id: 'c48', term: 'Reliability', definition: 'The consistency of measurement; the degree to which repeated measurements of the same behavior under the same conditions yield the same results; in applied settings, typically assessed through interobserver agreement (IOA).', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'Two observers independently record the frequency of a student\'s on-task behavior during the same session and obtain counts of 22 and 24 — their high agreement (91.7% IOA) indicates reliable measurement of the behavior.' },
  { id: 'c49', term: 'Validity', definition: 'The extent to which a measurement procedure actually measures what it is intended to measure; a measure is valid if it captures the behavior of interest and not some other behavior or artifact.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A BCBA uses a duration measure to assess "engagement" but the client frequently stares blankly at the activity — the measure lacks validity because duration of proximity to materials does not capture the intended construct of active engagement.' },
  { id: 'c50', term: 'Believability', definition: 'The degree to which consumers and other stakeholders find the data credible and trustworthy; enhanced by transparent data collection procedures, IOA checks, and clear operational definitions.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A BCBA presents treatment outcome data to a school team — the data\'s believability is strengthened by showing IOA scores above 90% across sessions and by having an independent observer collect data during 30% of sessions.' },
  { id: 'c55', term: 'Measurement Bias', definition: 'A systematic, consistent error in measurement that causes observed values to consistently overestimate or underestimate the true value; may result from observer expectations, reactivity, or flaws in the measurement system.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'An observer who knows a client is in the treatment phase consistently records slightly higher rates of appropriate behavior than a naive observer — this systematic overestimation is measurement bias driven by expectation effects.' },
  { id: 'c56', term: 'Observer Reactivity', definition: 'A change in the behavior of the person being observed that occurs because they know they are being observed; a threat to the external validity and representativeness of behavioral data.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A student who normally engages in frequent off-task behavior sits quietly and completes work whenever the BCBA enters the classroom to collect data — observer reactivity that makes the data unrepresentative of typical performance.' },
  { id: 'c65', term: 'Data', definition: 'Quantitative or qualitative observations recorded systematically during measurement; the raw numerical values that form the basis for graphing, analysis, and clinical decision-making in behavior analysis.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A BCBA records the number of correct mand responses per session across 20 sessions — these numerical values are the data that will be plotted on a line graph to evaluate the effectiveness of the mand training program.' },
  { id: 'c66', term: 'Graph', definition: 'A visual display of data that uses a coordinate system to show the relationship between two or more variables; in behavior analysis, the primary tool for communicating and analyzing behavioral data.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A BCBA plots session number on the x-axis and rate of problem behavior on the y-axis, creating a line graph that allows visual inspection of the data trend across baseline and treatment phases.' },
  { id: 'c67', term: 'Line Graph', definition: 'The most common type of graph in behavior analysis; displays data points connected by lines to show changes in behavior over time; the x-axis represents time (sessions, days) and the y-axis represents the measure of behavior.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A BCBA uses a line graph to display a client\'s daily frequency of appropriate requests across 30 sessions, with vertical phase change lines separating baseline from intervention phases.' },
  { id: 'c73', term: 'Equal-Interval Graph', definition: 'A graph scale in which equal distances on the y-axis represent equal amounts of behavior; the standard scale used in most behavior analytic graphs; appropriate for absolute comparisons of behavior change.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'On an equal-interval scale, the visual distance between 0 and 10 responses per minute is the same as between 10 and 20 — making a change from 2 to 4 appear the same size as a change from 12 to 14, even though the former is a 100% increase.' },
  { id: 'c75', term: 'Precision Teaching', definition: 'A measurement and instructional system developed by Ogden Lindsley that uses the Standard Celeration Chart to display and analyze behavior frequency data; emphasizes fluency building and uses celeration (rate of change in rate) as the primary measure of learning.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A teacher uses precision teaching to track a student\'s oral reading fluency — daily 1-minute timings are plotted on the Standard Celeration Chart, and the celeration line shows whether the student\'s rate of improvement meets the weekly learning target.' },
  { id: 'c76', term: 'Split-Middle Line of Progress', definition: 'A method of drawing a trend line through behavioral data by dividing the data into two equal halves, finding the median data point in each half, and drawing a line through those two median points; used for visual analysis of trend.', domain: 'C', domainFull: 'Measurement & Data Collection', example: 'A BCBA applies the split-middle method to 10 baseline data points — dividing them into two groups of 5, finding the median x and y values in each group, and drawing a line through those two points to estimate the baseline trend for comparison with treatment data.' },
  { id: 'd2', term: 'Internal Validity', definition: 'The degree to which an experiment demonstrates that changes in the dependent variable were caused by the independent variable and not by extraneous variables.', domain: 'D', domainFull: 'Experimental Design', example: 'A researcher uses an ABAB design and controls for time of day, therapist, and setting to ensure that behavior change during intervention phases is caused by the token economy (IV), not by other factors.' },
  { id: 'd3', term: 'External Validity', definition: 'The degree to which the results of an experiment can be generalized to other subjects, settings, behaviors, and time periods.', domain: 'D', domainFull: 'Experimental Design', example: 'A study demonstrating FCT effectiveness with one child in a clinic has limited external validity. When the same effect is replicated across 10 children in three different settings, external validity is substantially increased.' },
  { id: 'd4', term: 'Baseline Logic', definition: 'The three-part logical framework underlying single-case experimental designs: prediction (the future course of behavior without intervention), verification (ruling out extraneous variables), and replication (repeating the effect).', domain: 'D', domainFull: 'Experimental Design', example: 'In an ABAB design: stable baseline predicts future behavior (prediction); returning to baseline rules out history as a cause (verification); the effect occurring twice across both B phases confirms the relationship (replication).' },
  { id: 'd5', term: 'Reversal Design (ABAB)', definition: 'A single-case experimental design in which baseline and treatment conditions are alternated to demonstrate experimental control; requires the behavior to be reversible.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA measures self-injury during baseline (A), introduces DRO (B), withdraws DRO and self-injury returns to baseline levels (A), then reintroduces DRO and self-injury decreases again (B)  -  experimental control is demonstrated.' },
  { id: 'd6', term: 'Multiple Baseline Design', definition: 'A single-case experimental design in which the intervention is introduced sequentially across two or more behaviors, settings, or subjects; does not require reversal of behavior.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA introduces a social skills intervention for greeting first, then sharing, then turn-taking  -  each behavior changes only when the intervention is applied to it, demonstrating experimental control without reversal.' },
  { id: 'd7', term: 'Multiple Probe Design', definition: 'A variation of the multiple baseline design in which baseline data are collected intermittently (probed) rather than continuously, reducing the burden of continuous measurement.', domain: 'D', domainFull: 'Experimental Design', example: 'A researcher teaches three academic skills sequentially. Instead of measuring all three every session, she probes skills 2 and 3 only once per week until the intervention is applied to them  -  reducing session time without sacrificing experimental logic.' },
  { id: 'd8', term: 'Alternating Treatments Design (ATD)', definition: 'A single-case experimental design in which two or more conditions are rapidly alternated to compare their effects on behavior; also called multi-element design.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA alternates DTT and NET conditions across sessions to compare their effects on a child\'s vocabulary acquisition. After 10 sessions, the data paths separate, showing NET produces higher rates of correct responding.' },
  { id: 'd9', term: 'Changing Criterion Design', definition: 'A single-case experimental design in which the criterion for reinforcement is changed systematically; experimental control is demonstrated when behavior matches each successive criterion.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA uses a changing criterion design to reduce screen time: reinforcement requires ≤90 min/day (phase 1), then ≤75 min (phase 2), then ≤60 min (phase 3). Screen time matches each new criterion, demonstrating experimental control.' },
  { id: 'd10', term: 'Maturation (Threat to Internal Validity)', definition: 'A threat to internal validity in which observed changes in behavior are due to natural developmental processes rather than the independent variable.', domain: 'D', domainFull: 'Experimental Design', example: 'A 2-year-old\'s language improves during a 6-month intervention study. Because language development occurs naturally at this age, it is unclear whether the intervention or normal maturation caused the improvement.' },
  { id: 'd11', term: 'History (Threat to Internal Validity)', definition: 'A threat to internal validity in which observed changes in behavior are due to events outside the experiment that coincide with the intervention.', domain: 'D', domainFull: 'Experimental Design', example: 'A child\'s aggression decreases during an intervention study. The researcher later learns the child\'s parents started family therapy at the same time  -  the family therapy is a history threat that could explain the behavior change.' },
  { id: 'd12', term: 'Observer Drift', definition: 'A gradual, unintentional change in an observer\'s application of the measurement criteria over time, threatening measurement reliability.', domain: 'D', domainFull: 'Experimental Design', example: 'An observer who initially records only forceful hits gradually begins recording light touches as aggression over several weeks  -  her operational definition has drifted, inflating the frequency count and threatening data validity.' },
  { id: 'd13', term: 'Observer Bias', definition: 'A systematic distortion in measurement that occurs when an observer\'s expectations or knowledge of the experimental conditions influences their recording of behavior.', domain: 'D', domainFull: 'Experimental Design', example: 'An observer who knows the intervention is expected to reduce aggression records ambiguous physical contact as non-aggressive during intervention phases but as aggressive during baseline  -  her expectations are systematically distorting her data.' },
  { id: 'd15', term: 'Direct Replication', definition: 'Repeating an experiment under the same conditions with the same or similar participants to confirm the reliability of a finding.', domain: 'D', domainFull: 'Experimental Design', example: 'A researcher replicates a token economy study with a second group of children in the same classroom setting using the same procedures  -  if results match, the finding is considered reliable.' },
  { id: 'd16', term: 'Systematic Replication', definition: 'Repeating an experiment while intentionally varying one or more conditions (e.g., different participants, settings, or behaviors) to extend the generality of a finding.', domain: 'D', domainFull: 'Experimental Design', example: 'After demonstrating that FCT reduces aggression in a clinic setting, a researcher replicates the study in a school setting with a different population  -  if results hold, external validity is extended.' },
  { id: 'd18', term: 'Intersubject Replication', definition: 'Demonstrating a functional relationship by replicating an experimental effect across multiple participants; a key feature of multiple baseline designs.', domain: 'D', domainFull: 'Experimental Design', example: 'In a multiple baseline across participants design, the same intervention produces behavior change in three different children when introduced at different time points  -  the effect is replicated across subjects, strengthening the causal claim.' },
  { id: 'd19', term: 'Confounding Variable', definition: 'An uncontrolled variable that co-varies with the independent variable and may provide an alternative explanation for changes in the dependent variable; threatens internal validity.', domain: 'D', domainFull: 'Experimental Design', example: 'A researcher introduces a new token economy at the same time a child starts a new medication. When behavior improves, it is unclear whether the token economy or the medication caused the change  -  the medication is a confounding variable.' },
  { id: 'd20', term: 'Parametric Analysis', definition: 'An experimental approach in which the value or magnitude of an independent variable is systematically varied across conditions to determine the functional relationship between the parameter and behavior.', domain: 'D', domainFull: 'Experimental Design', example: 'Testing DRO intervals of 30s, 60s, and 120s to determine which produces the greatest reduction in problem behavior.' },
  { id: 'd21', term: 'Experimental Design', definition: 'The arrangement of conditions in a study to allow a researcher to determine whether changes in the dependent variable are caused by the independent variable rather than by extraneous variables; in behavior analysis, single-case designs are the primary experimental framework.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA uses an A-B-A-B withdrawal design to evaluate whether a token economy (independent variable) causes reductions in off-task behavior (dependent variable), demonstrating experimental control through repeated reversals.' },
  { id: 'd22', term: 'Baseline', definition: 'A condition in a study in which the independent variable is absent or withheld; provides a measure of the naturally occurring level of the dependent variable against which the effects of the independent variable are compared.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA collects 10 sessions of data on a student\'s rate of self-injury before introducing an intervention — this pre-intervention data is the baseline that will serve as the comparison standard for evaluating treatment effects.' },
  { id: 'd23', term: 'Steady State Responding', definition: 'A pattern of behavior that shows little variability in its measured dimensional quantities over time; the preferred state of baseline data before introducing an independent variable, as it provides a stable basis for comparison.', domain: 'D', domainFull: 'Experimental Design', example: 'After 8 sessions, a student\'s rate of problem behavior stabilizes at 3–4 instances per session with no clear trend — this steady state responding indicates the baseline is stable enough to introduce the intervention.' },
  { id: 'd24', term: 'Stable Baseline', definition: 'A baseline data pattern showing minimal variability and no systematic trend in the direction of expected treatment effects; the criterion that must be met before introducing an independent variable to ensure valid comparison.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA waits until the baseline data path shows no upward or downward trend and stays within a 20% range of the mean before introducing the treatment — a stable baseline that will allow clear detection of treatment effects.' },
  { id: 'd25', term: 'Variable Baseline', definition: 'A baseline data pattern showing high variability or inconsistency in the measured behavior; makes it difficult to predict future performance and to detect treatment effects; a threat to internal validity.', domain: 'D', domainFull: 'Experimental Design', example: 'A student\'s baseline data ranges from 0 to 15 instances of problem behavior per session with no consistent pattern — this variable baseline makes it impossible to determine whether subsequent changes are due to the intervention or natural variability.' },
  { id: 'd26', term: 'Ascending Baseline', definition: 'A baseline data pattern showing an increasing trend in the direction of expected treatment improvement; a threat to internal validity when the target behavior is one that should increase, because improvement may be due to the trend rather than the intervention.', domain: 'D', domainFull: 'Experimental Design', example: 'A student\'s baseline rate of correct responses is already increasing by 2 per session — this ascending baseline means that any increase during treatment cannot be attributed solely to the intervention, threatening internal validity.' },
  { id: 'd27', term: 'Descending Baseline', definition: 'A baseline data pattern showing a decreasing trend; a threat to internal validity when the target behavior is one that should decrease, because the reduction may be due to the trend rather than the intervention.', domain: 'D', domainFull: 'Experimental Design', example: 'A client\'s baseline rate of aggression is already decreasing by 1 instance per session — this descending baseline means that any reduction during treatment cannot be attributed solely to the intervention without additional experimental controls.' },
  { id: 'd28', term: 'Experimental Control', definition: 'The degree to which an experimenter can demonstrate that changes in the dependent variable are caused by the independent variable and not by extraneous variables; established through systematic replication of the effect across conditions, participants, or settings.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA demonstrates experimental control in an A-B-A-B design when problem behavior reliably increases during baseline (A) phases and reliably decreases during treatment (B) phases — the repeated pattern rules out coincidence as an explanation.' },
  { id: 'd29', term: 'Extraneous Variable', definition: 'Any variable other than the independent variable that could potentially influence the dependent variable; a threat to internal validity that experimental designs attempt to control or rule out.', domain: 'D', domainFull: 'Experimental Design', example: 'During a study on a new teaching procedure, a student\'s medication is changed — this medication change is an extraneous variable that could explain any behavioral improvement, making it difficult to attribute the change to the teaching procedure alone.' },
  { id: 'd31', term: 'Single-Case Designs', definition: 'A family of experimental designs in which each participant serves as their own control; the effects of the independent variable are evaluated by comparing the participant\'s behavior across different conditions rather than by comparing groups of participants.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA uses a single-case design to evaluate an intervention with one student — the student\'s own baseline data serves as the comparison standard, eliminating the need for a control group and making the design practical for applied settings.' },
  { id: 'd33', term: 'Affirmation of the Consequent', definition: 'A logical fallacy in which a researcher concludes that a specific cause produced an observed effect because the effect is consistent with the cause, without ruling out other possible causes; the basis for the scientific requirement to demonstrate experimental control.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA introduces a token economy and behavior improves — concluding the token economy caused the improvement without ruling out other changes (new teacher, medication change) commits the fallacy of affirming the consequent.' },
  { id: 'd34', term: 'Research Question', definition: 'A clearly stated, testable question that guides the design and conduct of a study; specifies the independent variable, dependent variable, and the population or participants of interest.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA formulates the research question: "Does the implementation of a token economy reduce the frequency of off-task behavior in students with ADHD during independent work periods?" — a testable question that guides all subsequent design decisions.' },
  { id: 'd36', term: 'A-B-A-B Design', definition: 'An experimental design consisting of two baseline phases (A) alternating with two treatment phases (B); the most common reversal design; demonstrates experimental control through two replications of the treatment effect and ends in the treatment condition.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA uses an A-B-A-B design — problem behavior is high in A1, decreases in B1, increases in A2, and decreases again in B2 — two replications of the effect that strongly demonstrate the treatment caused the behavior change.' },
  { id: 'd37', term: 'Withdrawal Design', definition: 'An experimental design in which the independent variable is introduced and then removed (withdrawn) to demonstrate that the behavior change is controlled by the independent variable; the A-B-A and A-B-A-B designs are the most common withdrawal designs.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA uses a withdrawal design by removing the token economy (independent variable) after behavior has improved — if problem behavior returns to baseline levels, the withdrawal demonstrates that the token economy was responsible for the improvement.' },
  { id: 'd40', term: 'Irreversibility', definition: 'A condition in which a behavior that has been changed by an intervention does not return to baseline levels when the intervention is withdrawn; limits the use of reversal designs because the reversal phase cannot demonstrate experimental control.', domain: 'D', domainFull: 'Experimental Design', example: 'After teaching a student to read 50 sight words, the BCBA withdraws the teaching procedure — but the student continues to read the words correctly because the skill has been acquired and is irreversible, making a reversal design inappropriate for this behavior.' },
  { id: 'd42', term: 'Sequence Effects', definition: 'Changes in behavior that result from the order in which conditions are presented rather than from the conditions themselves; a threat to internal validity in alternating treatments and multielement designs; controlled by counterbalancing.', domain: 'D', domainFull: 'Experimental Design', example: 'In an alternating treatments design, a student performs better in whichever condition is presented second because they are warmed up — this sequence effect could be mistaken for a genuine difference between the two conditions if not controlled by counterbalancing.' },
  { id: 'd43', term: 'Multiple Treatment Interference', definition: 'A threat to external validity in which the effects of one treatment condition influence the effects of another treatment condition when multiple conditions are applied to the same participant; a limitation of multielement and alternating treatments designs.', domain: 'D', domainFull: 'Experimental Design', example: 'A student who receives both praise and tokens in alternating sessions may respond to praise differently than a student who receives only praise — the presence of the token condition changes how the student responds to praise, limiting the generalizability of the praise-only findings.' },
  { id: 'd53', term: 'Treatment Integrity', definition: 'The degree to which the independent variable is implemented as planned and described; also called procedural fidelity; essential for valid conclusions about treatment effectiveness and for replication.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA uses a procedural fidelity checklist to verify that a therapist delivers each component of a DTT program correctly during 30% of sessions — high treatment integrity (>90%) ensures that the data reflect the intended intervention.' },
  { id: 'd54', term: 'Procedural Fidelity', definition: 'The degree to which each step of an intervention procedure is implemented exactly as specified; synonymous with treatment integrity; measured by comparing actual implementation against a written protocol or checklist.', domain: 'D', domainFull: 'Experimental Design', example: 'A supervisor observes a therapist implementing a prompting hierarchy and scores each step on a fidelity checklist — the therapist correctly implements 18 of 20 steps (90% procedural fidelity), indicating the intervention is being delivered as intended.' },
  { id: 'd55', term: 'Treatment Drift', definition: 'A gradual, unplanned change in the implementation of an intervention over time, such that the procedure being used differs from the original protocol; a threat to internal validity and replication.', domain: 'D', domainFull: 'Experimental Design', example: 'A therapist who initially follows a strict prompting hierarchy begins to skip steps after several weeks of implementation — this treatment drift means the data no longer reflect the original intervention, threatening the validity of conclusions about its effectiveness.' },
  { id: 'd61', term: 'Social Validity', definition: 'The degree to which the goals, procedures, and outcomes of an intervention are acceptable and meaningful to the client, family, and other stakeholders; assessed through consumer satisfaction surveys, interviews, or normative comparisons.', domain: 'D', domainFull: 'Experimental Design', example: 'After a successful intervention, a BCBA surveys the parents and teacher to assess whether they found the goals important, the procedures acceptable, and the outcomes meaningful — high social validity ratings indicate the intervention was valued by those it affected.' },
  { id: 'd64', term: 'Type I Error', definition: 'A false positive conclusion in which a researcher incorrectly concludes that the independent variable had an effect when it actually did not; the probability of a Type I error is the alpha level in statistical hypothesis testing.', domain: 'D', domainFull: 'Experimental Design', example: 'A researcher concludes that a new teaching procedure improved performance when the improvement was actually due to natural maturation — a Type I error that could lead to widespread adoption of an ineffective procedure.' },
  { id: 'd65', term: 'Type II Error', definition: 'A false negative conclusion in which a researcher incorrectly concludes that the independent variable had no effect when it actually did; may result from insufficient statistical power, high variability, or an insensitive measurement system.', domain: 'D', domainFull: 'Experimental Design', example: 'A researcher concludes that a new reinforcement procedure had no effect on behavior when it actually did produce a meaningful change — a Type II error that could lead to abandonment of an effective procedure due to high data variability masking the true effect.' },
  { id: 'e1', term: 'Informed Consent', definition: 'A process by which a client or guardian voluntarily agrees to participate in assessment or treatment after receiving complete, accurate, and understandable information about the procedures, risks, and alternatives.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e2', term: 'Assent', definition: 'A client\'s affirmative agreement to participate in assessment or treatment, distinct from legal consent (which requires capacity); particularly relevant for minors and individuals with limited decision-making capacity.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e3', term: 'Confidentiality', definition: 'The ethical obligation to protect client information from unauthorized disclosure; governed by professional ethics codes, HIPAA, and applicable laws.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e4', term: 'Scope of Competence', definition: 'The range of professional activities for which a BCBA has the necessary education, training, and supervised experience; BCBAs must only practice within this range.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e5', term: 'Dual Relationship', definition: 'A situation in which a BCBA has both a professional and a personal or business relationship with a client, supervisee, or trainee; must be avoided when it could impair objectivity or harm the client.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e7', term: 'Behavior Intervention Plan (BIP)', definition: 'A written document that describes the function of a problem behavior, the antecedent and consequence strategies to address it, and the replacement behavior to be taught.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e8', term: 'Scope of Practice', definition: 'The range of services, procedures, and responsibilities that a behavior analyst is qualified to provide based on their education, training, supervised experience, and credentials.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e9', term: 'Cultural Humility', definition: 'An ongoing process of self-reflection and learning about one\'s own cultural biases and the cultural backgrounds of clients, with the goal of providing culturally responsive services.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e10', term: 'Mandatory Reporting', definition: 'The legal and ethical obligation to report suspected abuse, neglect, or exploitation of vulnerable individuals to the appropriate authorities.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e11', term: 'Beneficence', definition: 'The ethical obligation to act in the best interest of the client; requires that interventions produce meaningful benefit and that potential harms are minimized.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e13', term: 'Autonomy', definition: 'The ethical principle of respecting the right of individuals to make informed decisions about their own care; in ABA, includes obtaining assent and honoring client preferences when possible.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e15', term: 'BACB Ethics Code', definition: 'The professional standards document published by the Behavior Analyst Certification Board that outlines the ethical obligations of certified behavior analysts; organized around responsibility to clients, supervisees, the profession, and society.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e16', term: 'Multiple Relationships', definition: 'A situation in which a behavior analyst has both a professional and a personal, financial, or other relationship with a client, supervisee, or research participant; generally avoided because they can impair objectivity and harm the other party.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e17', term: 'Conflict of Interest', definition: 'A situation in which a behavior analyst has personal, financial, or professional interests that could improperly influence their professional judgment or actions on behalf of a client.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e18', term: 'Whistleblowing', definition: 'The act of reporting unethical, illegal, or harmful practices by a colleague or organization to the appropriate authority; a professional obligation under the BACB Ethics Code when internal resolution fails.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e19', term: 'Dignity and Basic Rights', definition: 'The ethical obligation to treat all clients with respect, protect their fundamental rights, and ensure that interventions do not demean, humiliate, or deprive them of basic necessities.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e20', term: 'Stakeholder', definition: 'Any individual or group with a legitimate interest in the outcomes of a behavior analytic program, including the client, family members, caregivers, teachers, and funding agencies.', domain: 'E', domainFull: 'Ethical & Professional Issues' },
  { id: 'e21', term: 'Ethics', definition: 'The branch of philosophy concerned with moral principles and values that guide human conduct; in behavior analysis, a set of professional obligations derived from the BACB Ethics Code that governs the behavior of certificants toward clients, supervisees, colleagues, and the public.', domain: 'E', domainFull: 'Ethical & Professional Issues', example: 'A BCBA consults the BACB Ethics Code when a parent requests a procedure that may be effective but raises concerns about client dignity — using the ethical framework to weigh competing obligations and make a defensible decision.' },
  { id: 'e23', term: 'Compliance Code', definition: 'A set of enforceable rules and standards that a professional organization requires its members to follow, with specific consequences for violations; distinct from aspirational ethical principles in that compliance is mandatory and subject to formal disciplinary review.', domain: 'E', domainFull: 'Ethical & Professional Issues', example: 'The BACB Ethics Code functions as a compliance code — certificants who violate its standards may face formal investigations, sanctions, suspension, or revocation of their certification, not merely professional disapproval.' },
  { id: 'e24', term: 'Disciplinary Standards', definition: 'The formal procedures and criteria used by a credentialing body to investigate alleged violations of its ethics code and to impose sanctions on certificants found to have violated those standards.', domain: 'E', domainFull: 'Ethical & Professional Issues', example: 'The BACB\'s disciplinary standards outline the process by which a complaint against a certificant is reviewed, investigated, and adjudicated — including the range of sanctions from required training to permanent revocation of certification.' },
  { id: 'e25', term: 'Negligence', definition: 'A failure to exercise the standard of care that a reasonably competent professional would provide under similar circumstances, resulting in harm or risk of harm to a client; a form of professional misconduct that may constitute both an ethical violation and a legal liability.', domain: 'E', domainFull: 'Ethical & Professional Issues', example: 'A BCBA who fails to conduct a functional assessment before implementing a punishment procedure, resulting in an increase in problem behavior, may be found negligent for not following the standard of care expected of a competent behavior analyst.' },
  { id: 'e26', term: 'Risk-Benefit Analysis', definition: 'A systematic evaluation of the potential harms and potential benefits of a proposed intervention or course of action, used to determine whether the expected benefits justify the risks involved; required before implementing restrictive or aversive procedures.', domain: 'E', domainFull: 'Ethical & Professional Issues', example: 'Before recommending a contingent electric stimulation device for severe self-injury, a BCBA conducts a risk-benefit analysis weighing the potential reduction in life-threatening self-injury against the pain, potential tissue damage, and psychological effects of the procedure.' },
  { id: 'e27', term: 'Countercontrol', definition: 'Behavior emitted by an individual in response to aversive control by another person or institution, aimed at reducing, escaping, or retaliating against that control; a natural consequence of coercive or overly restrictive intervention strategies.', domain: 'E', domainFull: 'Ethical & Professional Issues', example: 'A client who is subjected to highly restrictive procedures without assent begins refusing to attend sessions, destroying materials, and engaging in aggression toward staff — countercontrol behaviors that signal the intervention is experienced as aversive and coercive.' },
  { id: 'e28', term: 'Fraudulent Conduct', definition: 'Intentional deception or misrepresentation for personal gain, including falsifying data, billing for services not rendered, misrepresenting credentials, or fabricating research results; a serious ethical and legal violation.', domain: 'E', domainFull: 'Ethical & Professional Issues', example: 'A BCBA who bills an insurance company for 40 hours of direct therapy in a week when only 20 hours were provided is engaging in fraudulent conduct — a violation of the BACB Ethics Code and potentially a criminal offense.' },
  { id: 'f1', term: 'Indirect Assessment', definition: 'An FBA method that gathers information about behavior through interviews, rating scales, and questionnaires without direct observation of the behavior.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f2', term: 'Descriptive Assessment', definition: 'An FBA method that involves direct observation of behavior in the natural environment, recording antecedents and consequences as they naturally occur (e.g., ABC recording, scatter plot).', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f3', term: 'Functional Analysis (FA)', definition: 'An FBA method that involves the systematic manipulation of antecedent and consequence variables to experimentally identify the function(s) of a behavior; the most rigorous method.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f4', term: 'ABC Narrative Recording', definition: 'A descriptive assessment method in which an observer records antecedents, behaviors, and consequences as they occur in sequence, in narrative form.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f5', term: 'Preference Assessment', definition: 'A systematic procedure for identifying stimuli that may function as reinforcers for an individual, prior to implementing a reinforcement-based intervention.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f6', term: 'Topography-Based Definition', definition: 'A behavior definition that describes what the behavior looks like (its physical form), without reference to its function or effect on the environment.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f7', term: 'Function-Based Definition', definition: 'A behavior definition that describes the behavior in terms of its effect on the environment or its function, rather than its physical form.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f8', term: 'Habituation', definition: 'A decrease in responding to a stimulus following repeated presentations of that stimulus; a form of respondent behavior change.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f9', term: 'Respondent Extinction', definition: 'A procedure in which a conditioned stimulus (CS) is repeatedly presented without the unconditioned stimulus (US), resulting in a decrease in the conditioned response (CR).', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f10', term: 'Stimulus Class', definition: 'A group of stimuli that share common elements (formal, temporal, or functional) and evoke the same response or are treated similarly by an organism.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f11', term: 'Response Class', definition: 'A group of responses that, despite differing in topography, all produce the same effect on the environment and are maintained by the same reinforcer.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f12', term: 'Functional Behavior Assessment (FBA)', definition: 'A systematic process for identifying the antecedents and consequences that maintain a problem behavior; includes indirect, descriptive, and experimental (functional analysis) methods.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f13', term: 'Paired Stimulus Preference Assessment', definition: 'A preference assessment in which two stimuli are presented simultaneously and the client selects one; each stimulus is paired with every other, and selection frequency determines a preference hierarchy.', domain: 'F', domainFull: 'Behavior Assessment', example: 'A client is presented with pairs of toys and the therapist records which item is chosen each time to rank preferences.' },
  { id: 'f14', term: 'Multiple Stimulus Without Replacement (MSWO)', definition: 'A preference assessment in which multiple stimuli are presented simultaneously and the chosen item is removed after each selection; continues until all items have been selected or the client stops responding.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f15', term: 'Free Operant Observation', definition: 'A preference assessment in which the client has unrestricted access to multiple stimuli for a set period and the time spent with each item is recorded to infer preference.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f17', term: 'ABC Analysis', definition: 'A descriptive assessment method in which the antecedent events, the target behavior, and the consequences that follow are systematically recorded to identify potential controlling variables.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f18', term: 'Operational Definition', definition: 'A precise, observable, and measurable description of a behavior that specifies its topography or function clearly enough that two independent observers would agree on whether the behavior occurred.', domain: 'F', domainFull: 'Behavior Assessment', example: 'Aggression is defined as any instance of hitting, kicking, or biting that makes physical contact with another person.' },
  { id: 'f19', term: 'Ecological Assessment', definition: 'A broad evaluation of the physical, social, and instructional environments in which a client lives and learns; used to identify setting events, barriers to participation, and environmental modifications that may support behavior change.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'f21', term: 'Generalized Imitation', definition: 'A behavioral repertoire in which an organism imitates novel behaviors it has never been reinforced for imitating, as a result of a history of reinforcement for imitating a variety of modeled behaviors.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'After being reinforced for imitating many different actions, a child imitates a novel action (touching their nose) the first time it is modeled, without having been directly reinforced for that specific imitation — generalized imitation has developed.' },
  { id: 'f22', term: 'Modeling', definition: 'A procedure in which a desired behavior is demonstrated for the learner to observe and imitate; the model performs the target behavior and the learner is reinforced for producing a topographically similar response.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'A BCBA demonstrates how to tie shoelaces step by step while the student watches, then prompts the student to imitate each step — modeling provides a visual prompt that supplements verbal instructions.' },
  { id: 'f23', term: 'Video Modeling', definition: 'A modeling procedure in which the learner watches a video recording of a model performing the target behavior before attempting to perform the behavior themselves; effective for teaching social, daily living, and vocational skills.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'A BCBA creates a video of a peer demonstrating how to initiate a conversation and shows it to a student with autism before each social skills session — video modeling provides a consistent, repeatable model that the student can watch multiple times.' },
  { id: 'f24', term: 'Video Self-Modeling', definition: 'A variation of video modeling in which the learner watches a video of themselves performing the target behavior correctly; the video may be edited to show only successful performances, providing a model of the learner\'s own competent behavior.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'A BCBA records a student performing a social skill correctly (using physical guidance and editing to remove errors), then shows the student the video before practice sessions — video self-modeling uses the student\'s own successful performance as the model.' },
  { id: 'f26', term: 'Imitation Training', definition: 'A systematic procedure for teaching a learner to imitate modeled behaviors; typically involves reinforcing successive approximations to the modeled behavior and eventually reinforcing only responses that closely match the model.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'A BCBA uses imitation training with a child who does not yet imitate — the therapist models "arms up" and physically prompts the child to raise their arms, then fades the prompt while reinforcing progressively closer approximations to the modeled action.' },
  { id: 'f27', term: 'Response Differentiation', definition: 'The process by which differential reinforcement produces a change in the form, topography, or other dimensional quantity of a behavior; the mechanism through which shaping works.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'A BCBA reinforces only those vocalizations that are louder than 60 dB and withholds reinforcement for quieter vocalizations — response differentiation produces a change in the loudness dimension of the vocalization behavior.' },
  { id: 'f28', term: 'Successive Approximations', definition: 'A series of behaviors that progressively resemble the terminal behavior in shaping; each approximation is reinforced until it occurs reliably, then the criterion is raised to require a closer approximation to the terminal behavior.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'In teaching a child to say "ball," a BCBA first reinforces any vocalization, then only "buh" sounds, then "ba," then "bal," then "ball" — each step is a successive approximation that moves the child closer to the terminal behavior.' },
  { id: 'f32', term: 'Behavior Chain', definition: 'A sequence of individual behaviors in which each response produces a stimulus that functions as a conditioned reinforcer for the preceding response and as a discriminative stimulus for the next response; the final response produces the terminal reinforcer.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'Hand washing is a behavior chain: turning on the water (S1) → wetting hands (S2) → applying soap (S3) → scrubbing (S4) → rinsing (S5) → drying (terminal reinforcer) — each step is both reinforced by the completion of the prior step and signals the next step.' },
  { id: 'f33', term: 'Behavior Chain with a Limited Hold', definition: 'A behavior chain in which the terminal reinforcer is available only if the entire chain is completed within a specified time limit; the limited hold adds a temporal requirement to the chain.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'A BCBA teaches a student to complete a morning routine (get dressed, eat breakfast, pack backpack) within 30 minutes to catch the school bus — the bus departure time is the limited hold that adds a temporal requirement to the behavior chain.' },
  { id: 'f37', term: 'Behavior Chain Interruption Strategy', definition: 'A procedure in which a step in an established behavior chain is interrupted to create an opportunity for the learner to request assistance, a missing item, or a preferred activity; used to teach manding and communication skills.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'A BCBA sets up a snack routine and then removes the cup from the chain at the "pour juice" step — the interruption creates a motivating operation for the student to request the cup, providing a naturalistic opportunity to practice manding.' },
  { id: 'f39', term: 'Resistance to Extinction', definition: 'The degree to which a behavior persists after reinforcement is discontinued; behavior that has been maintained on intermittent reinforcement schedules is more resistant to extinction than behavior maintained on continuous reinforcement.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'A student whose problem behavior was intermittently reinforced (sometimes ignored, sometimes attended to) shows high resistance to extinction when extinction is implemented — the intermittent reinforcement history makes the behavior persist much longer than if it had been continuously reinforced.' },
  { id: 'f48', term: 'Fixed-Time Schedule', definition: 'A schedule of reinforcement in which a reinforcer is delivered after a fixed amount of time has elapsed, regardless of the organism\'s behavior; a noncontingent reinforcement schedule used as an antecedent intervention to reduce problem behavior.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'A BCBA delivers attention to a student every 3 minutes regardless of whether the student is engaging in problem behavior — the fixed-time schedule of noncontingent attention reduces the motivating operation for attention-maintained problem behavior.' },
  { id: 'f49', term: 'Variable-Time Schedule', definition: 'A schedule of reinforcement in which a reinforcer is delivered after variable amounts of time have elapsed, regardless of the organism\'s behavior; a noncontingent reinforcement schedule that is more resistant to extinction than a fixed-time schedule.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'A BCBA delivers attention at variable intervals averaging 3 minutes regardless of the student\'s behavior — the variable-time schedule of noncontingent attention is less predictable than a fixed-time schedule and may be more effective at reducing the motivating operation for attention-maintained behavior.' },
  { id: 'f51', term: 'Functional Communication Training (FCT)', definition: 'An intervention in which the problem behavior is placed on extinction and a functionally equivalent communicative response is taught and reinforced; the replacement behavior accesses the same reinforcer that previously maintained the problem behavior.', domain: 'F', domainFull: 'Behavior-Change Procedures', example: 'A BCBA places a student\'s aggression (maintained by escape) on extinction and teaches the student to hand a "break" card to request escape from demands — FCT replaces the problem behavior with a socially acceptable communicative response that accesses the same escape reinforcer.' },
  { id: 'g1', term: 'Differential Reinforcement of Alternative Behavior (DRA)', definition: 'A procedure in which reinforcement is delivered for a specific alternative behavior while withholding reinforcement for the problem behavior.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g2', term: 'Differential Reinforcement of Incompatible Behavior (DRI)', definition: 'A procedure in which reinforcement is delivered for a behavior that is physically incompatible with the problem behavior (cannot occur at the same time).', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g3', term: 'Differential Reinforcement of Other Behavior (DRO)', definition: 'A procedure in which reinforcement is delivered when the problem behavior has not occurred for a specified interval of time. Two primary subtypes: (1) Whole-interval DRO  -  reinforcement is delivered if the behavior is absent for the entire interval; (2) Momentary DRO  -  reinforcement is delivered if the behavior is absent at the moment the interval ends. Momentary DRO is easier to implement in naturalistic settings.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A 5-minute whole-interval DRO: if Leo does not engage in self-injury at any point during the 5 minutes, he earns a token. A momentary DRO checks only at the 5-minute mark.' },
  { id: 'g6', term: 'Escape Extinction', definition: 'A procedure in which escape from a demand is no longer provided contingent on problem behavior; the individual must complete the task regardless of problem behavior.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g10', term: 'Prompting', definition: 'Supplementary antecedent stimuli that increase the probability that a correct response will occur; used to teach new behaviors.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g11', term: 'Fading', definition: 'The gradual removal of prompts across trials so that the behavior comes under the control of the natural SD rather than the prompt.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g12', term: 'Task Analysis', definition: 'The process of breaking a complex behavior chain into its component steps; used to teach chained behaviors systematically.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g14', term: 'Token Economy', definition: 'A conditioned reinforcement system in which tokens are earned contingent on target behaviors and later exchanged for backup reinforcers.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g18', term: 'Antecedent Intervention', definition: 'Any modification to the environment that occurs before the behavior to reduce the likelihood of problem behavior or increase the likelihood of appropriate behavior.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g19', term: 'Consequence Intervention', definition: 'Any modification to the events that follow behavior to change its future frequency; includes reinforcement and punishment procedures.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g20', term: 'Discrete Trial Training (DTT)', definition: 'A structured teaching method consisting of a discriminative stimulus, a prompt (if needed), a response opportunity, and a consequence; trials are massed or distributed and data are recorded trial by trial.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'The therapist presents a picture card (SD), waits for the child to label it, and delivers a token for a correct response.' },
  { id: 'g21', term: 'Natural Environment Teaching (NET)', definition: 'Instruction that occurs in the natural context during everyday activities and routines, using the learner\'s motivation and natural reinforcers; contrasted with the structured format of DTT.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g22', term: 'Incidental Teaching', definition: 'A naturalistic teaching strategy in which the instructor arranges the environment to create opportunities for the learner to initiate, then uses the learner\'s initiation as the occasion to prompt and reinforce a more elaborate response.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g23', term: 'Errorless Learning', definition: 'A teaching strategy in which prompts are provided at the outset of instruction to prevent errors, ensuring the learner consistently contacts reinforcement; prompts are faded systematically over time.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A most-to-least prompting hierarchy is used so the learner never makes an error during initial skill acquisition.' },
  { id: 'g24', term: 'Error Correction', definition: 'A procedure used after an incorrect response in which the correct response is prompted, practiced, and reinforced; used to reduce future errors without inadvertently reinforcing incorrect responding.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g25', term: 'Forward Chaining', definition: 'A chaining procedure in which the first step of a task analysis is taught first; subsequent steps are added sequentially as each preceding step is mastered.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'Teaching hand-washing by first training the learner to turn on the faucet, then adding the next step once mastered.' },
  { id: 'g26', term: 'Backward Chaining', definition: 'A chaining procedure in which the last step of a task analysis is taught first; the trainer completes all preceding steps and the learner performs only the final step, then works backward through the chain.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g27', term: 'Total Task Chaining', definition: 'A chaining procedure in which the learner is prompted through all steps of a task analysis in every session; used when the learner has prerequisite skills and the chain is not too long.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g30', term: 'Response Prompt', definition: 'A prompt that involves a behavior of the trainer — such as a physical assist, model, gesture, or verbal cue — that increases the probability of a correct response in the presence of the target discriminative stimulus.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A teacher physically guides a student\'s hand to write the letter \'A\' (physical prompt), then models the writing motion (model prompt), then points to the starting position (gestural prompt) across successive teaching sessions.' },
  { id: 'g31', term: 'Stimulus Prompt', definition: 'A prompt that involves a change to the target discriminative stimulus itself — such as its position, size, color, or intensity — to increase the probability of a correct response, without adding a separate trainer behavior.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA initially presents the correct picture card in a larger size than the distractor cards; as the student\'s accuracy improves, the size difference is gradually reduced until all cards are the same size.' },
  { id: 'g32', term: 'Within-Stimulus Prompt', definition: 'A type of stimulus prompt in which a feature of the target discriminative stimulus is exaggerated or highlighted to direct attention to the relevant dimension, with the exaggeration gradually faded until the stimulus appears in its natural form.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'When teaching letter discrimination, a BCBA initially presents the letter \'b\' with the vertical line greatly elongated compared to the circle, then gradually reduces the exaggeration until the letter appears in standard form.' },
  { id: 'g34', term: 'Physical Prompt', definition: 'A type of response prompt in which the trainer provides direct physical contact — ranging from full hand-over-hand guidance to a light touch — to assist the learner in completing a motor response.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA uses full hand-over-hand guidance to help a student with autism complete a puzzle piece placement, then fades to wrist guidance, then a light touch on the elbow, then no contact as the student gains independence.' },
  { id: 'g35', term: 'Gestural Prompt', definition: 'A type of response prompt in which the trainer uses a physical movement — such as pointing, nodding, or looking toward the correct stimulus — to direct the learner\'s attention or response without physical contact.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A teacher points to the correct answer card when a student hesitates during a receptive identification task, providing directional information without touching the student or the materials.' },
  { id: 'g36', term: 'Model Prompt', definition: 'A type of response prompt in which the trainer demonstrates the target behavior for the learner to imitate, either immediately before the learner\'s response opportunity (live modeling) or via video (video modeling).', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA demonstrates the correct handwashing sequence for a student with an intellectual disability, then immediately provides the student with an opportunity to imitate the sequence.' },
  { id: 'g37', term: 'Verbal Prompt', definition: 'A type of response prompt in which the trainer provides a spoken cue — such as a partial word, full instruction, or question — to increase the likelihood of a correct response in the presence of the target discriminative stimulus.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A teacher says \'What do you say when someone gives you something?\' to prompt a student to say \'thank you\' in a social situation where the natural SD (receiving an item) has not yet acquired stimulus control.' },
  { id: 'g38', term: 'Visual Prompt', definition: 'A type of response prompt in which a written, pictorial, or graphic cue — such as a picture schedule, written checklist, or color-coded guide — is provided to direct the learner\'s response.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA provides a student with a picture activity schedule showing each step of the morning routine in sequence, allowing the student to complete the routine independently by following the visual cues.' },
  { id: 'g39', term: 'Most-to-Least Prompting', definition: 'A prompting procedure in which the most intrusive level of prompt necessary to ensure a correct response is provided at the beginning of training, and the level of prompt intrusiveness is systematically decreased across trials or sessions as the learner demonstrates accuracy.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA begins teaching tooth brushing with full hand-over-hand guidance, then fades to wrist guidance, then a light touch, then a gestural prompt, then no prompt as the student masters each step.' },
  { id: 'g40', term: 'Least-to-Most Prompting', definition: 'A prompting procedure in which the least intrusive prompt is provided first following an incorrect response or no response within a specified latency, with progressively more intrusive prompts added until a correct response occurs.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'After presenting the SD \'Touch red\', a BCBA waits 3 seconds; if no response, provides a gestural prompt; if still no response, provides a model; if still no response, provides a physical prompt — always starting with the least intrusive option.' },
  { id: 'g41', term: 'Graduated Guidance', definition: 'A prompting procedure in which the trainer provides the level of physical guidance necessary to ensure a correct response on a moment-to-moment basis, immediately reducing guidance as the learner initiates the correct movement and immediately increasing guidance if the learner deviates.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'During toothbrushing training, a BCBA maintains hand-over-hand contact but immediately releases pressure and follows the student\'s hand as soon as the student begins moving correctly, only re-applying guidance if the student stops or deviates.' },
  { id: 'g45', term: 'Prompt Fading', definition: 'The systematic reduction of a prompt\'s intrusiveness, frequency, or magnitude over successive trials or sessions until the prompt is no longer needed and the target stimulus alone controls the correct response.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA fades a gestural prompt by first pointing directly at the correct answer, then pointing in the general direction, then making a smaller gesture, then no gesture — measuring accuracy at each step to ensure the student maintains correct responding.' },
  { id: 'g46', term: 'Transfer of Stimulus Control', definition: 'The process by which stimulus control shifts from a prompt (which initially evokes the correct response) to the target discriminative stimulus (which should ultimately control the response) through systematic prompt fading or time delay procedures.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'After a student learns to identify pictures only when the teacher points to them, the BCBA fades the pointing prompt so that the pictures themselves — not the teacher\'s gesture — come to control the correct identification response.' },
  { id: 'g69', term: 'Behavior Chain Interruption Strategy (BCIS)', definition: 'A procedure in which a step in a previously mastered behavior chain is interrupted or blocked, creating an establishing operation that increases the motivative value of completing the chain and can be used to teach manding or other communicative responses.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA interrupts a student\'s snack preparation routine by removing the cup just before the student would pour juice, creating an establishing operation for the juice that increases the likelihood the student will request the cup.' },
  { id: 'g93', term: 'High-Probability Request Sequence (High-p)', definition: 'An antecedent intervention in which a series of requests with a high probability of compliance (high-p requests) are presented immediately before a low-probability request (low-p request), using behavioral momentum to increase compliance with the low-p request.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'Before asking a student to complete a non-preferred math worksheet (low-p), a BCBA presents three requests the student reliably complies with (\'Give me five\', \'Touch your nose\', \'Clap your hands\'), then immediately presents the math worksheet.' },
  { id: 'g99', term: 'Token', definition: 'A conditioned reinforcer used in a token economy that acquires its reinforcing value through pairing with backup reinforcers; tokens are delivered immediately contingent on target behaviors and are later exchanged for backup reinforcers.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'Poker chips, star stickers, check marks on a card, and points on a digital system are all examples of tokens — they have no inherent value but acquire reinforcing function through their established exchange value for backup reinforcers.' },
  { id: 'g100', term: 'Backup Reinforcer', definition: 'A stimulus or activity for which tokens can be exchanged in a token economy; the backup reinforcer is the ultimate source of reinforcing value for the tokens, and the token economy\'s effectiveness depends on the backup reinforcers being genuinely preferred by the individual.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'In a classroom token economy, backup reinforcers include 10 minutes of computer time, a preferred snack, or the opportunity to be class helper — items and activities identified as highly preferred through preference assessments.' },
  { id: 'g101', term: 'Group Contingency', definition: 'A behavior change procedure in which the consequences for individuals are determined by the behavior of the group as a whole, a subset of the group, or an individual member of the group; group contingencies can be dependent, independent, or interdependent.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA implements a group contingency in a classroom: if the class collectively earns 20 points for on-task behavior during the week, the entire class earns a pizza party on Friday.' },
  { id: 'g102', term: 'Dependent Group Contingency', definition: 'A group contingency in which the same consequence is delivered to all members of the group contingent on the behavior of one individual or a small subset of the group; the group\'s reinforcement depends on the performance of a specific member.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA selects one student each day as the \'mystery student\' and tells the class that if the mystery student earns 10 points, the entire class earns extra recess; the class\'s reinforcement depends on the selected individual\'s behavior.' },
  { id: 'g103', term: 'Independent Group Contingency', definition: 'A group contingency in which the same contingency is in effect for all members of the group, but each individual\'s reinforcement is determined solely by their own behavior; members do not affect each other\'s access to reinforcement.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA announces that any student who completes their homework every day this week earns a homework pass; each student\'s reinforcement is determined independently by their own homework completion, not by peers\' behavior.' },
  { id: 'g104', term: 'Interdependent Group Contingency', definition: 'A group contingency in which the same consequence is delivered to all members of the group contingent on the group as a whole meeting a specified criterion; all members must meet the criterion (or the group\'s aggregate performance must meet the criterion) for any member to receive reinforcement.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA implements an interdependent group contingency in which the class earns a movie party only if every student in the class completes at least 80% of their assignments correctly during the week.' },
  { id: 'g105', term: 'Good Behavior Game', definition: 'An interdependent group contingency procedure in which a class is divided into teams, and each team earns a point (or loses a point) for rule violations; the team with the fewest violations (or all teams below a criterion) earns a reward at the end of the period.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA divides a class into two teams and places a mark on the board for each team when a member breaks a classroom rule; at the end of the period, the team with fewer marks earns 5 minutes of free time.' },
  { id: 'g106', term: 'Contingency Contract', definition: 'A written document that specifies the behavior required of an individual and the consequences (reinforcers or punishers) that will follow; contracts are negotiated between the individual and a significant other (teacher, parent, therapist) and signed by both parties.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA and a high school student with ADHD negotiate and sign a contract specifying that if the student completes all assigned work during study hall (3 days per week), the student earns 30 minutes of video game time on Friday afternoon.' },
  { id: 'g107', term: 'Level System', definition: 'A token economy variant in which individuals progress through a hierarchy of levels, with each level associated with different privileges and behavioral requirements; advancement to higher levels requires meeting increasingly stringent behavioral criteria.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A residential program uses a 4-level system: Level 1 students have restricted privileges and must meet basic behavioral criteria to advance; Level 4 students have the most privileges and serve as mentors, having demonstrated sustained behavioral improvement.' },
  { id: 'g108', term: 'Hero Procedure', definition: 'A dependent group contingency in which one student is randomly selected as the \'hero\', and the entire class earns reinforcement if the hero meets a specified behavioral criterion; the procedure uses peer support and social motivation to improve the hero\'s behavior.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA uses the hero procedure for a student with frequent disruptive behavior: the student is selected as the hero, and if they earn 8 or more points during the day, the entire class earns extra recess — motivating peers to support the hero\'s appropriate behavior.' },
  { id: 'g110', term: 'Self-Management', definition: 'The personal application of behavior change tactics to produce a desired change in one\'s own behavior; involves arranging antecedents and consequences to influence the frequency, duration, or topography of one\'s own target behaviors.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA teaches a student to use a self-management package: the student sets a timer (antecedent), monitors their own on-task behavior on a data sheet (self-monitoring), and self-delivers a token for each interval of on-task behavior (self-reinforcement).' },
  { id: 'g111', term: 'Self-Monitoring', definition: 'A self-management procedure in which an individual observes and records their own behavior; self-monitoring serves both as a data collection method and as a behavior change procedure, as the act of recording often produces reactivity that changes the monitored behavior.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A student uses a wrist counter to record each instance of nail-biting throughout the day; the act of counting the behavior produces reactivity — the student becomes more aware of the behavior and its frequency decreases over time.' },
  { id: 'g117', term: 'Habit Reversal', definition: 'A self-management procedure for reducing repetitive behaviors (such as tics, nail-biting, or hair-pulling) that involves awareness training, competing response training, and social support; the individual learns to detect the urge to perform the habit and substitute an incompatible competing response.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA uses habit reversal to treat a student\'s hair-pulling: the student is trained to detect early signs of the urge to pull (awareness training) and to clench their fist for 1 minute whenever the urge occurs (competing response training), with parents providing praise for using the competing response.' },
  { id: 'g120', term: 'Generalization Probe', definition: 'A measurement procedure in which the target behavior is assessed in a non-training context (different setting, stimulus, or person) without providing reinforcement, to determine whether generalization has occurred without directly training the behavior in that context.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA teaches a student to greet peers in the therapy room and then conducts generalization probes in the cafeteria and playground — presenting the natural greeting opportunity without providing prompts or reinforcement to assess whether generalization has occurred.' },
  { id: 'g123', term: 'Instructional Setting', definition: 'The setting in which a behavior is directly trained and reinforced; the instructional setting is distinguished from the generalization setting, and effective programming requires planning for transfer from the instructional to the generalization setting.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA conducts discrete trial training in a one-on-one therapy room (instructional setting) and separately assesses whether the trained skills transfer to the student\'s classroom and home (generalization settings).' },
  { id: 'g126', term: 'Response Maintenance', definition: 'The continuation of a target behavior after the training contingencies (prompts, reinforcement schedules) have been thinned or removed; the degree to which a behavior persists over time without ongoing intervention.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA fades the token economy used to teach a student\'s on-task behavior, transitioning to natural classroom reinforcement; response maintenance is evaluated by measuring on-task behavior 3 and 6 months after the token economy is removed.' },
  { id: 'g128', term: 'Program Common Stimuli', definition: 'A generalization programming strategy in which stimuli from the generalization setting are incorporated into the training setting, so that the trained behavior comes under the control of stimuli that are also present in the natural environment.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA teaching a student to order food at a restaurant brings actual menus, trays, and a mock counter into the therapy room during training, so the student\'s ordering behavior comes under the control of stimuli present in the natural restaurant setting.' },
  { id: 'g129', term: 'Multiple-Exemplar Training', definition: 'A generalization programming strategy in which training is conducted across multiple examples of the stimulus class, so that the trained behavior generalizes to untrained members of the same class; effective for establishing concept learning and generalized responding.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA teaches a student to identify \'cup\' using 10 different cups (plastic, glass, paper, large, small, colored) rather than a single cup, so the student\'s identification response generalizes to novel cups not used during training.' },
  { id: 'g130', term: 'General Case Analysis', definition: 'A generalization programming strategy in which the full range of stimulus variations and response variations in the generalization setting is analyzed, and training examples are selected to sample the full range, ensuring that the trained behavior generalizes to all relevant instances.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'Before teaching a student to use a crosswalk, a BCBA conducts a general case analysis identifying all relevant variations (different crosswalk signals, traffic patterns, pedestrian densities) and selects training examples that sample the full range of these variations.' },
  { id: 'g133', term: 'Behavior Trap', definition: 'A naturally occurring contingency in the environment that \'traps\' a newly acquired behavior by providing rich, naturally occurring reinforcement for the behavior, maintaining it without continued programmed intervention.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA teaches a student the minimal social skills needed to initiate play with peers; once the student begins playing with peers, the natural reinforcement of peer interaction (laughter, games, social reciprocity) traps and maintains the social behavior without further programmed intervention.' },
  { id: 'g134', term: 'Contrived Contingency', definition: 'A reinforcement or punishment contingency that is deliberately arranged by a behavior analyst or trainer and does not occur naturally in the environment; contrived contingencies are used to establish behaviors that will eventually come under the control of natural contingencies.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA delivers token reinforcement for a student\'s hand-raising behavior — a contrived contingency that does not naturally occur in the classroom; the goal is to establish hand-raising so it eventually comes under the control of natural teacher attention.' },
  { id: 'g136', term: 'Indiscriminable Contingency', definition: 'A contingency arrangement in which the learner cannot reliably discriminate when reinforcement is available versus when it is not, typically achieved through intermittent reinforcement schedules or delayed reinforcement; indiscriminable contingencies promote response maintenance.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA thins a token economy to a variable-ratio schedule and introduces delayed reinforcement, creating an indiscriminable contingency in which the student cannot predict when the next reinforcer will be delivered — promoting maintenance of the target behavior.' },
  { id: 'g137', term: 'Contrived Mediating Stimulus', definition: 'A stimulus that is introduced during training and carried by the learner into the generalization setting, serving as a bridge between the training and generalization contexts; the mediating stimulus evokes the trained behavior in the new setting.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA teaches a student to use a picture card as a self-prompt for the steps of a vocational task; the student carries the picture card from the training setting to the work setting, where it serves as a contrived mediating stimulus that evokes the trained task sequence.' },
  { id: 'g138', term: 'Natural Maintaining Contingency', definition: 'A reinforcement contingency that exists in the natural environment and is capable of maintaining a behavior without continued programmed intervention; identifying and connecting behavior to natural maintaining contingencies is a key goal of generalization programming.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA identifies that peer attention is a natural maintaining contingency for a student\'s social initiations; by teaching the student to initiate interactions that reliably produce peer attention, the BCBA connects the behavior to a natural contingency that will maintain it.' },
  { id: 'rr-fc-behavior-skills-training-bst', term: 'Behavior Skills Training (BST)', definition: 'A training package consisting of four components: instruction (telling the learner what to do), modeling (demonstrating the skill), rehearsal (having the learner practice), and feedback (providing corrective and positive feedback); used to teach a wide range of skills.', domain: 'G', domainFull: 'Behavior-Change Procedures', example: 'A BCBA trains a new RBT to implement discrete trial teaching by: (1) explaining the procedure, (2) demonstrating correct implementation, (3) having the RBT practice with a confederate, and (4) providing feedback — using all four BST components.' },
  { id: 'h1', term: 'Socially Significant Behavior', definition: 'Behavior that is important to the individual and to society; the target of ABA interventions should produce meaningful improvements in quality of life.', domain: 'H', domainFull: 'Selecting & Implementing Interventions' },
  { id: 'h2', term: 'Behavioral Goal (Objective)', definition: 'A written statement specifying the target behavior, conditions under which it will occur, and the criterion for mastery; should be observable, measurable, and achievable.', domain: 'H', domainFull: 'Selecting & Implementing Interventions' },
  { id: 'h3', term: 'Maintenance', definition: 'The continuation of a behavior change after the intervention has been reduced or withdrawn; a key goal of ABA programming.', domain: 'H', domainFull: 'Selecting & Implementing Interventions' },
  { id: 'h4', term: 'Generalization', definition: 'The occurrence of a behavior change across settings, people, stimuli, or responses beyond those directly trained; includes stimulus generalization and response generalization.', domain: 'H', domainFull: 'Selecting & Implementing Interventions' },
  { id: 'h7', term: 'Crisis Plan', definition: 'A component of a BIP that specifies the procedures to follow when a client engages in dangerous behavior that poses immediate risk of harm.', domain: 'H', domainFull: 'Selecting & Implementing Interventions' },
  { id: 'h8', term: 'Discharge Planning', definition: 'The systematic process of preparing a client and their support system for the reduction or termination of ABA services, including transition goals and maintenance strategies.', domain: 'H', domainFull: 'Selecting & Implementing Interventions' },
  { id: 'h10', term: 'Treatment Acceptability', definition: 'The degree to which consumers (clients, caregivers, teachers) judge an intervention to be appropriate, fair, and reasonable for the presenting problem; a component of social validity.', domain: 'H', domainFull: 'Selecting & Implementing Interventions' },
  { id: 'h13', term: 'Transition Planning', definition: 'The process of systematically preparing a client for a change in services, placement, or life stage; includes identifying new support systems, transferring skills, and fading current supports to promote independence.', domain: 'H', domainFull: 'Selecting & Implementing Interventions' },
  { id: 'h20', term: 'Competing Stimulus Assessment', definition: 'A systematic evaluation of stimuli that may compete with the reinforcer maintaining a problem behavior; used to identify items that can be used as enriched environments or alternative reinforcers in intervention.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'A BCBA presents various toys and activities to a child who engages in automatically-maintained stereotypy and measures which items produce the greatest reduction in stereotypy  -  those items are used in the treatment package.' },
  { id: 'h24', term: 'Brief Functional Analysis', definition: 'A condensed version of a functional analysis in which test conditions are conducted for shorter durations or fewer sessions to quickly identify the function of a behavior; used when time or resources do not permit a full functional analysis.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'A BCBA conducts 5-minute test conditions across four functions (attention, escape, tangible, alone) in a single session to quickly identify the likely function of a student\'s aggression before designing a treatment.' },
  { id: 'h25', term: 'Conditional Probability', definition: 'The probability that a behavior will occur given that a specific antecedent or consequence has occurred; used in descriptive functional behavior assessment to identify antecedent-behavior-consequence relationships.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'A BCBA calculates that self-injury occurs in 85% of intervals following a demand presentation — a high conditional probability that suggests escape as a likely function of the behavior.' },
  { id: 'h27', term: 'Contingency Reversal', definition: 'A procedure used within a functional analysis in which the contingency that maintains one behavior is applied to a different behavior to demonstrate that the contingency, not some other variable, controls the behavior.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'In a functional analysis, a BCBA reverses the contingency so that appropriate behavior produces escape instead of problem behavior — if appropriate behavior increases, the reversal confirms that escape reinforcement was maintaining the problem behavior.' },
  { id: 'h28', term: 'Functionally Equivalent', definition: 'Behaviors that produce the same type of reinforcement; in behavior analysis, a replacement behavior is functionally equivalent to a problem behavior when it accesses the same reinforcer that maintained the problem behavior.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'A student\'s aggression and a BCBA-taught hand-raising behavior are functionally equivalent if both produce teacher attention — the replacement behavior must access the same reinforcer to be an effective substitute for the problem behavior.' },
  { id: 'h29', term: 'Trial-Based Functional Analysis', definition: 'A variation of functional analysis in which brief test and control trials are embedded within the natural environment rather than conducted in a separate clinic or therapy room; allows functional analysis in classrooms and community settings.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'A BCBA embeds 5-minute attention test trials and control trials within a student\'s regular classroom routine, alternating them across the school day, to identify the function of disruptive behavior without removing the student from the classroom.' },
  { id: 'h30', term: 'Contingency Space Analysis', definition: 'A method of analyzing descriptive assessment data that plots the conditional probability of reinforcement given the occurrence of behavior against the conditional probability of reinforcement given the non-occurrence of behavior, to determine whether a contingency exists.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'A BCBA plots data showing that teacher attention follows problem behavior 80% of the time but follows appropriate behavior only 10% of the time — the contingency space analysis reveals a strong attention contingency maintaining the problem behavior.' },
  { id: 'h32', term: 'Descriptive Functional Behavior Assessment', definition: 'A method of functional behavior assessment in which the behavior analyst directly observes and records the antecedents and consequences of a target behavior in the natural environment without manipulating any variables.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'A BCBA conducts 10 hours of direct observation in a student\'s classroom, recording the antecedent, behavior, and consequence for each instance of problem behavior using an ABC recording form — a descriptive FBA that identifies patterns without experimental manipulation.' },
  { id: 'h33', term: 'Interview-Informed Synthesized Contingency Analysis', definition: 'A variation of functional analysis in which the test condition is based on the specific antecedent-behavior-consequence sequence identified through indirect assessment interviews, rather than testing each function separately; produces a synthesized condition that mirrors the natural environment.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'After an interview reveals that a student\'s aggression occurs when demands are presented and the teacher provides attention while removing the demand, a BCBA designs a test condition that simultaneously presents demands, provides attention contingent on aggression, and removes the demand — a synthesized condition that mirrors the natural contingency.' },
  { id: 'rr-fc-antecedent-based-intervention', term: 'Antecedent-Based Intervention', definition: 'A behavior-change procedure that modifies antecedent conditions (discriminative stimuli, motivating operations, or setting events) to prevent problem behavior or increase appropriate behavior before it occurs.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'A BCBA reduces a student\'s escape-maintained problem behavior by pre-teaching difficult tasks, offering choices, and providing high-preference activities before demanding tasks — modifying antecedents to reduce the motivation to escape.' },
  { id: 'rr-fc-extinction-procedure', term: 'Extinction Procedure', definition: 'A behavior-change procedure in which the reinforcer that previously maintained a problem behavior is identified and withheld contingent on the occurrence of that behavior; most effective when combined with reinforcement of alternative behavior.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'A BCBA instructs a teacher to no longer provide attention following a student\'s tantrums (which were maintained by attention) — using an extinction procedure by withholding the reinforcer that previously maintained the behavior.' },
  { id: 'rr-fc-pivotal-response-training-prt', term: 'Pivotal Response Training (PRT)', definition: 'A naturalistic behavioral intervention that targets pivotal areas of development (motivation, responsivity to multiple cues, self-management, and social initiations) to produce widespread improvements across many areas of functioning.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'A BCBA targets motivation and responsivity to multiple cues as pivotal behaviors in a child with autism, embedding learning opportunities in child-preferred activities and using natural reinforcers — using PRT to produce broad improvements across untrained behaviors.' },
  { id: 'rr-fc-social-skills-training', term: 'Social Skills Training', definition: 'A behavior-change approach that uses behavioral techniques (modeling, rehearsal, feedback, reinforcement) to teach specific social behaviors; targets skills such as conversation, perspective-taking, and peer interaction.', domain: 'H', domainFull: 'Selecting & Implementing Interventions', example: 'A BCBA uses behavioral skills training (instruction, modeling, rehearsal, feedback) to teach a student with autism to initiate conversations with peers, using role-play and video modeling — implementing a social skills training program.' },
  { id: 'i1', term: 'Performance Management', definition: 'The application of behavior analytic principles to improve the work-related behavior of employees or supervisees, including goal-setting, feedback, and reinforcement.', domain: 'I', domainFull: 'Personnel Supervision & Management' },
  { id: 'i2', term: 'Behavioral Skills Training (BST)', definition: 'A staff training package consisting of four components: instructions, modeling, rehearsal, and feedback; used to teach new skills to supervisees and staff.', domain: 'I', domainFull: 'Personnel Supervision & Management' },
  { id: 'i3', term: 'Performance Feedback', definition: 'Information provided to a supervisee about the accuracy and quality of their work, delivered in a timely and specific manner to improve future performance.', domain: 'I', domainFull: 'Personnel Supervision & Management' },
  { id: 'i4', term: 'Competency-Based Training', definition: 'A training approach in which advancement is contingent on demonstrated mastery of skills (meeting a performance criterion), rather than on time spent in training.', domain: 'I', domainFull: 'Personnel Supervision & Management' },
  { id: 'i5', term: 'Supervision Contract', definition: 'A written agreement between a supervisor and supervisee that specifies the goals, responsibilities, methods, and evaluation criteria for the supervisory relationship.', domain: 'I', domainFull: 'Personnel Supervision & Management' },
  { id: 'i6', term: 'Organizational Behavior Management (OBM)', definition: 'The application of behavior analysis to improve performance and safety in organizational settings; includes performance management, systems analysis, and behavior-based safety.', domain: 'I', domainFull: 'Personnel Supervision & Management' },
  { id: 'i9', term: 'Behavioral Systems Analysis', definition: 'The application of behavior analytic principles to analyze and improve the performance of entire organizations or systems; examines the interplay between individual behavior, processes, and organizational outcomes.', domain: 'I', domainFull: 'Personnel Supervision & Management' },
  { id: 'i10', term: 'Supervision Hours (BACB)', definition: 'The documented hours of fieldwork oversight required for BCBA certification; must meet BACB standards for frequency, format (individual vs. group), and content (unrestricted vs. restricted activities).', domain: 'I', domainFull: 'Personnel Supervision & Management' },
  { id: 'i11', term: 'BACB Supervision Model', definition: 'The BACB requires that supervisors hold current BCBA or BCaBA certification, complete an 8-hour supervision training, and provide supervision that is performance-based, competency-based, and individualized to the supervisee; supervision must constitute at least 5% of the hours accrued in a given period.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A BCBA supervisor schedules weekly individual and group supervision sessions, tracks hours using the BACB supervision form, and designs activities targeting the supervisee\'s specific skill gaps rather than using a generic curriculum.' },
  { id: 'i12', term: 'Performance Improvement Plan (PIP)', definition: 'A structured written document used when a supervisee\'s performance falls below an established criterion; specifies the target skill, current performance level, goal criterion, timeline, support resources, and consequences for non-improvement.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A supervisee\'s data collection accuracy is 62% across three consecutive observations. The supervisor creates a PIP specifying a goal of 90% accuracy within 6 weeks, with weekly BST sessions and a re-evaluation checkpoint at week 3.' },
  { id: 'i14', term: 'Supervisee Competency Assessment', definition: 'A systematic evaluation of a supervisee\'s knowledge and skill across the BACB task list domains; used to identify training priorities, document progress, and determine readiness for independent practice; tools include direct observation, role-play, and written assessments.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'At the start of supervision, a BCBA administers a written task list assessment and conducts three direct observations of the supervisee implementing a behavior intervention plan, then uses the results to prioritize skill areas for the supervision curriculum.' },
  { id: 'i15', term: 'Supervision Documentation', definition: 'The written record of all supervisory activities required by the BACB; must include the date, duration, type of supervision (individual or group), activities completed, and supervisor and supervisee signatures; retained for 7 years per BACB requirements.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'After each supervision meeting, the supervisor and supervisee both sign the BACB Experience Supervision Form documenting the date, hours accrued, and activities completed; these records are submitted when the supervisee applies for certification.' },
  { id: 'i17', term: 'Supervisor Self-Assessment', definition: 'The ongoing process by which a BCBA evaluates their own supervisory competence, identifies skill gaps, and seeks training or consultation to address them; required by the BACB Ethics Code as part of practicing within the boundaries of competence.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A BCBA who has never supervised a supervisee working with adults with intellectual disabilities seeks consultation from a more experienced colleague and completes continuing education in adult services before accepting a supervisee in that population.' },
  { id: 'rr-fc-acquisition', term: 'Acquisition', definition: 'The initial learning phase in which a new behavior is being established; characterized by increasing accuracy and consistency of responding as a result of reinforcement contingencies.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A child is learning to request \'water\' using PECS; during the acquisition phase, the response rate increases from 0 to 80% correct across sessions as the skill is being established for the first time.' },
  { id: 'rr-fc-distributed-trial-instruction', term: 'Distributed Trial Instruction', definition: 'An instructional arrangement in which trials of the same target skill are interspersed with trials of other skills or activities, or distributed across a session; promotes maintenance and generalization.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A BCBA embeds trials to teach a student to identify pictures of animals throughout the school day during natural routines (snack, circle time, transitions) rather than in a massed format — using distributed trial instruction to promote generalization.' },
  { id: 'rr-fc-fluency', term: 'Fluency', definition: 'A level of skill performance characterized by both accuracy and speed; fluent behavior is performed at a high rate with few errors and is more likely to be maintained and to generalize than behavior that is merely accurate.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A student can label 100 pictures per minute with 98% accuracy — demonstrating fluency (both accuracy and speed) in picture identification, which is associated with better retention and generalization than accuracy alone.' },
  { id: 'rr-fc-general-case-programming', term: 'General Case Programming', definition: 'A generalization programming strategy in which the full range of stimulus variations and response requirements in the natural environment is analyzed, and instruction is designed to cover the full range of relevant stimulus-response variations.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A BCBA teaches a student to use a microwave by training with multiple different microwaves (different brands, panel layouts, wattages) — using general case programming to ensure the student can operate any microwave encountered in the natural environment.' },
  { id: 'rr-fc-instructional-control', term: 'Instructional Control', definition: 'A condition in which the learner', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A BCBA establishes instructional control by pairing herself with reinforcement, using a relaxed instructional style, and ensuring high rates of reinforcement for compliance — creating conditions under which the student reliably follows instructions.' },
  { id: 'rr-fc-massed-trial-instruction', term: 'Massed Trial Instruction', definition: 'An instructional arrangement in which multiple trials of the same target skill are presented consecutively within a session; promotes rapid acquisition but may reduce motivation and generalization.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A BCBA runs 20 consecutive trials of a color identification task within a single session — using massed trial instruction to provide high-density practice opportunities for rapid skill acquisition.' },
  { id: 'rr-fc-mastery-criterion', term: 'Mastery Criterion', definition: 'A predetermined level of performance that must be achieved before a learner is considered to have mastered a skill and before instruction moves to the next skill; typically specified in terms of accuracy, rate, or both across multiple sessions.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A BCBA specifies that a student must label 9 out of 10 pictures correctly across three consecutive sessions before a skill is considered mastered and the program advances — using a mastery criterion to ensure durable learning.' },
  { id: 'rr-fc-matching-to-sample-mts', term: 'Matching-to-Sample (MTS)', definition: 'A procedure in which the learner is presented with a sample stimulus and must select the comparison stimulus that matches the sample from an array; used to teach conditional discriminations and stimulus equivalence relations.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A student is shown a picture of a cat (sample) and three comparison pictures (cat, dog, bird); the student selects the matching cat picture — demonstrating matching-to-sample, a conditional discrimination procedure.' },
  { id: 'rr-fc-probe', term: 'Probe', definition: 'A brief assessment of a learner', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A BCBA tests a student\'s ability to name untrained pictures of animals without providing reinforcement or prompts — conducting a probe to assess generalization of the naming skill to untrained stimuli.' },
  { id: 'rr-fc-skill-acquisition-program', term: 'Skill Acquisition Program', definition: 'A written plan that specifies the target skill, instructional procedures, prompting strategy, reinforcement schedule, mastery criterion, and data collection method for teaching a specific skill to a learner.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A BCBA develops a written program specifying the target behavior, teaching procedure, prompt hierarchy, reinforcement schedule, and mastery criterion for teaching a student to identify letters — creating a skill acquisition program.' },
  { id: 'rr-fc-sufficient-exemplar-training', term: 'Sufficient Exemplar Training', definition: 'A generalization programming strategy in which enough examples of the target stimulus class are trained until generalization to untrained members of the class occurs; the number of exemplars needed varies by individual and skill.', domain: 'I', domainFull: 'Personnel Supervision & Management', example: 'A BCBA teaches a student to greet 10 different people in 5 different settings until the student generalizes greetings to novel people and settings without additional training — using sufficient exemplar training to promote generalization.' },
  { id: 'rr-fc-abc-continuous-recording', term: 'ABC Continuous Recording', definition: 'A descriptive assessment method in which an observer records every occurrence of the target behavior along with the antecedent events that immediately preceded it and the consequent events that immediately followed it; produces a narrative or structured record of the three-term contingency as it occurs naturally in the environment without any programmed manipulation.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation', example: 'A BCBA observes a student in the classroom and records: (A) teacher gives a group instruction, (B) student shouts out an answer, (C) teacher praises the student  -  repeated entries like this across a session reveal that teacher attention may be reinforcing the calling-out behavior.' },
  { id: 'rr-fc-trend', term: 'Trend', definition: 'The direction and degree of systematic increase or decrease in the level of data points within a condition over time; typically described as accelerating (increasing), decelerating (decreasing), or zero-celerating (flat); one of the three primary dimensions used to evaluate graphed behavioral data alongside level and variability.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation', example: 'A BCBA examining a graph of a client\'s self-injurious behavior across a baseline phase notes a clear decelerating trend  -  the behavior is already decreasing before the intervention begins  -  which complicates any causal claim about the treatment effect.' },
  { id: 'rr-fc-carry-over-effect', term: 'Carry-Over Effect', definition: 'A threat to internal validity in which exposure to one condition influences responding in a subsequent condition, making it impossible to determine whether changes in the dependent variable are due to the new condition or to residual effects of the prior condition; particularly problematic in alternating treatments designs and reversal designs when behaviors do not return to baseline levels.', domain: 'D', domainFull: 'Experimental Design', example: 'In an A-B-A-B design, a BCBA finds that problem behavior does not return to baseline levels during the second A phase  -  the behavior may have been permanently altered by the B intervention, making it impossible to demonstrate experimental control through reversal.' },
  { id: 'rr-fc-bab-design', term: 'B-A-B Design', definition: 'A single-case experimental design that begins with a treatment phase (B), followed by a withdrawal phase (A), and then a return to treatment (B); used when withholding treatment at the outset would be unethical or impractical; provides a demonstration of experimental control but is considered weaker than the A-B-A-B design because it does not establish a true pre-intervention baseline.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA working with a child who engages in severe self-injury cannot ethically withhold treatment, so a B-A-B design is used: treatment is implemented first, then briefly withdrawn to demonstrate that behavior worsens without it, then reinstated  -  showing the treatment is responsible for behavior change.' },
  { id: 'rr-fc-causation', term: 'Causation (Functional Relation)', definition: 'The demonstration that a specific independent variable is responsible for changes in a dependent variable; established in single-case research through the systematic replication of an effect  -  showing that the behavior reliably changes when the independent variable is introduced and returns toward baseline when it is withdrawn; distinguished from correlation, which only shows that two variables co-vary.', domain: 'D', domainFull: 'Experimental Design', example: 'A BCBA demonstrates causation in an A-B-A-B design when problem behavior reliably decreases each time the FCT intervention is introduced (B phases) and reliably increases each time it is withdrawn (A phases)  -  the repeated pattern rules out coincidence and establishes a functional relation.' },
  { id: 'rr-fc-false-negative', term: 'False Negative (Type II Error)', definition: 'An error in which a researcher or clinician concludes that no functional relation exists between the independent and dependent variables when in fact a real effect is present; in behavioral assessment, a false negative occurs when a functional analysis fails to identify the true reinforcer maintaining a problem behavior, leading to an ineffective intervention.', domain: 'D', domainFull: 'Experimental Design', example: 'A functional analysis of a student\'s aggression yields undifferentiated results across all conditions, leading the BCBA to conclude the behavior is automatically reinforced  -  but the behavior is actually maintained by social attention that was inadvertently provided during all conditions, a false negative result.' },
  { id: 'rr-fc-false-positive', term: 'False Positive (Type I Error)', definition: 'An error in which a researcher or clinician concludes that a functional relation exists between the independent and dependent variables when in fact no real effect is present; in behavioral assessment, a false positive occurs when a functional analysis incorrectly identifies a reinforcer that does not actually maintain the problem behavior, leading to an intervention targeting the wrong function.', domain: 'D', domainFull: 'Experimental Design', example: 'A brief functional analysis shows elevated responding in the attention condition, leading the BCBA to implement an extinction-based intervention for attention-maintained behavior  -  but the behavior was actually maintained by escape, and the intervention fails because the analysis produced a false positive result.' },
  { id: 'sync-001', term: 'Adaptive Behavior Assessment', definition: 'A standardized evaluation of an individual\'s repertoire of skills across adaptive domains (communication, daily living, socialization, motor skills) using norm-referenced instruments to identify deficits and guide intervention planning.', example: 'See BACB Task List for Adaptive Behavior Assessment.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'sync-002', term: 'Alone Condition (FA)', definition: 'A test condition in a functional analysis in which the individual is left alone in a room with no social interaction, no demands, and no access to preferred items; elevated rates of problem behavior in this condition suggest the behavior is maintained by automatic reinforcement (i.e., the behavior produces its own sensory consequences).', example: 'See BACB Task List for Alone Condition (FA).', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync-003', term: 'Attention Condition (FA)', definition: 'A test condition in a functional analysis in which the therapist delivers brief social attention (e.g., a statement of concern) contingent on the problem behavior, while otherwise appearing to be occupied; elevated rates of problem behavior in this condition suggest the behavior is maintained by social positive reinforcement in the form of attention.', example: 'See BACB Task List for Attention Condition (FA).', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync-004', term: 'Contrived Free Operant Preference Assessment', definition: 'A preference assessment in which the assessor arranges a structured array of stimuli in a controlled setting; the individual is observed for approach responses and duration of engagement with each item; differs from naturalistic free operant in that stimuli and environment are arranged by the assessor.', example: 'See BACB Task List for Contrived Free Operant Preference Assessment.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'sync-005', term: 'Control (Experimental)', definition: 'A within-subject experimental design that begins with an intervention phase (B), followed by a return to baseline (A), and then a reinstatement of the intervention (B); used when it is unethical or impractical to begin with a baseline phase because the target behavior is dangerous or requires immediate treatment; provides less experimental control than an A-B-A-B design because the initial baseline is absent.', example: 'See BACB Task List for Control (Experimental).', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync-006', term: 'Emergent Relations', definition: 'Stimulus relations that emerge without direct training as a result of training other relations; in stimulus equivalence, emergent relations include symmetry (B→A after training A→B) and transitivity (A→C after training A→B and B→C); the emergence of untrained relations is a defining feature of derived relational responding and stimulus equivalence.', example: 'See BACB Task List for Emergent Relations.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync-007', term: 'Escape Condition (FA)', definition: 'A test condition in a functional analysis in which demands or aversive tasks are presented and the therapist removes the demand briefly contingent on the problem behavior; elevated rates of problem behavior in this condition suggest the behavior is maintained by negative reinforcement in the form of escape from demands.', example: 'See BACB Task List for Escape Condition (FA).', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync-008', term: 'Generative Performance', definition: 'The ability to produce novel responses or combinations of responses that were never directly trained; in verbal behavior, generative performance refers to the production of novel verbal responses (e.g., novel sentences, novel tacts) that emerge from the combination of trained verbal operants; a hallmark of fluent and flexible behavioral repertoires.', example: 'See BACB Task List for Generative Performance.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync-009', term: 'Instructions', definition: 'Verbal or written antecedents that describe the expected behavior, the conditions under which it should occur, or the consequences that will follow; function as rule-governed behavior when they specify a contingency; effective instructions are clear, specific, and within the learner\'s current repertoire.', example: 'See BACB Task List for Instructions.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'sync-010', term: 'Latency-Based Functional Analysis', definition: 'A functional analysis format in which the latency to the first occurrence of problem behavior (rather than rate or frequency) is used as the dependent variable; particularly useful for low-rate or dangerous behaviors; shorter latency in a test condition relative to the control condition indicates that condition\'s reinforcer is maintaining the behavior.', example: 'See BACB Task List for Latency-Based Functional Analysis.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'sync-011', term: 'Level', definition: 'The absolute value of data on the y-axis of a graph; described in terms of the mean or median of data points within a phase; one of the three primary dimensions used to evaluate behavioral data, alongside trend and variability; level changes between phases indicate the magnitude of behavior change.', example: 'See BACB Task List for Level.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync-012', term: 'Multiple Control (FA)', definition: 'A functional analysis outcome or interpretation in which a problem behavior is found to be maintained by more than one source of reinforcement (e.g., both attention and escape); behavior maintained by multiple functions typically requires intervention components that address each maintaining contingency.', example: 'See BACB Task List for Multiple Control (FA).', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync-013', term: 'Naturalistic Free Operant Preference Assessment', definition: 'A preference assessment in which the individual is observed in their natural environment with free access to a variety of stimuli; approach responses, duration of engagement, and frequency of interaction with each stimulus are recorded without the assessor arranging or presenting stimuli; reflects naturally occurring preferences in the individual\'s own environment.', example: 'See BACB Task List for Naturalistic Free Operant Preference Assessment.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'sync-014', term: 'Play Condition (FA)', definition: 'A control condition in a functional analysis in which the individual has free access to preferred items and activities, no demands are placed, and the therapist provides noncontingent attention; this condition is designed to produce low rates of problem behavior and serves as a comparison baseline for the test conditions.', example: 'See BACB Task List for Play Condition (FA).', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync-015', term: 'Rules', definition: 'Verbal statements that describe a behavioral contingency  --  specifying what behavior is expected, under what conditions, and what consequences will follow; rules function as discriminative stimuli for rule-governed behavior; effective rules are clear, specific, consistently enforced, and paired with appropriate consequences.', example: 'See BACB Task List for Rules.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync-016', term: 'Skills Assessment', definition: 'A systematic evaluation of an individual\'s current behavioral repertoire to identify skill strengths and deficits; used to establish baseline performance and guide the selection of instructional targets; examples include the VB-MAPP, ABLLS-R, and AFLS.', example: 'See BACB Task List for Skills Assessment.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'sync-017', term: 'Train Loosely', definition: 'A generalization programming strategy in which training is conducted with intentional variation in non-critical dimensions of the instructional stimuli (e.g., varying materials, trainers, and settings) to promote generalization to untrained stimulus variations.', example: 'See BACB Task List for Train Loosely.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'sync-018', term: 'Undifferentiated Functional Analysis', definition: 'A functional analysis outcome in which rates of problem behavior are elevated across all test conditions (attention, escape, alone) and the control condition, making it impossible to identify a single maintaining function; may indicate multiple controlling variables, methodological issues, or that the behavior is maintained by a combination of functions.', example: 'See BACB Task List for Undifferentiated Functional Analysis.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync-019', term: 'Variability', definition: 'The degree of scatter or spread of data points around the central tendency within a phase of a graph; high variability indicates inconsistent responding and makes it difficult to identify a stable trend or evaluate the effect of an intervention; one of the three primary dimensions used to evaluate behavioral data alongside level and trend.', example: 'See BACB Task List for Variability.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-001', term: 'Arbitrary Relations', definition: 'Relations between stimuli that are established by social convention rather than by the physical properties of the stimuli; the basis of symbolic behavior and language.', example: 'See BACB Task List for Arbitrary Relations.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-002', term: 'Automatic Reinforcement  -  Functional Analysis', definition: 'In a functional analysis, automatic reinforcement is indicated when behavior persists at elevated rates in the alone condition and/or the ignore condition, suggesting the reinforcer is intrinsic to the behavior rather than socially mediated.', example: 'See BACB Task List for Automatic Reinforcement  -  Functional Analysis.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-003', term: 'Behavior Change Tactic', definition: 'A specific, technologically defined procedure for changing behavior; derived from principles of behavior and used to achieve behavior change goals; examples include shaping, chaining, and differential reinforcement.', example: 'See BACB Task List for Behavior Change Tactic.', domain: 'H', domainFull: 'Selecting & Implementing Interventions' },
  { id: 'sync2-004', term: 'Behavior Checklist', definition: 'An indirect assessment tool that lists specific behaviors and asks informants to indicate whether each behavior occurs; used to identify target behaviors and assess behavioral repertoires.', example: 'See BACB Task List for Behavior Checklist.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'sync2-005', term: 'Codic', definition: 'A verbal operant in which a written or printed verbal stimulus controls a written or printed verbal response, with point-to-point correspondence and formal similarity between stimulus and response; the written equivalent of the echoic.', example: 'See BACB Task List for Codic.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-006', term: 'Contextual Control', definition: 'The influence of contextual stimuli (setting events, background stimuli) on the effectiveness of discriminative stimuli and motivating operations; the same SD may have different effects in different contexts.', example: 'See BACB Task List for Contextual Control.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-007', term: 'Contextual Stimulus', definition: 'A background stimulus that alters the function of other stimuli without directly evoking behavior; may function as a conditional discriminative stimulus or as a setting event that influences the effectiveness of other antecedents.', example: 'See BACB Task List for Contextual Stimulus.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-008', term: 'Copying Text', definition: 'A verbal operant in which the speaker copies written text; involves point-to-point correspondence and formal similarity between the written stimulus and the written response; a form of textual behavior.', example: 'See BACB Task List for Copying Text.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-009', term: 'Derived Stimulus Relations', definition: 'Relations between stimuli that emerge without direct training based on a history of training other relations; the foundation of stimulus equivalence and relational frame theory.', example: 'See BACB Task List for Derived Stimulus Relations.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-010', term: 'Dimensions of ABA (REACCS)', definition: 'The seven defining characteristics of applied behavior analysis identified by Baer, Wolf, and Risley (1968): Applied, Behavioral, Analytic, Technological, Conceptually Systematic, Effective, and Generality (remembered by the acronym REACCS or similar).', example: 'See BACB Task List for Dimensions of ABA (REACCS).', domain: 'A', domainFull: 'Behaviorism & Philosophical Foundations' },
  { id: 'sync2-011', term: 'Distinction Relations', definition: 'In relational frame theory, relations of difference or non-sameness between stimuli (e.g., A is different from B); the opposite of equivalence relations.', example: 'See BACB Task List for Distinction Relations.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-012', term: 'Duplic', definition: 'A class of verbal operants in which the verbal response reproduces the formal properties of the controlling verbal stimulus with point-to-point correspondence; includes both echoics (auditory to auditory) and codics (written to written).', example: 'See BACB Task List for Duplic.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-013', term: 'Extended Mand', definition: 'A mand emitted under a novel motivating operation or in novel stimulus conditions that were not part of original mand training, resulting in a request that was not directly trained under those specific conditions.', example: 'See BACB Task List for Extended Mand.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-014', term: 'Extended Tact', definition: 'A tact that occurs in the presence of a novel stimulus that shares some but not all properties with the original training stimulus, resulting in a response that was not directly trained under that specific stimulus condition.', example: 'See BACB Task List for Extended Tact.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-015', term: 'Formal Similarity', definition: 'A formal property of verbal behavior in which the controlling stimulus and the verbal response share the same sense mode (e.g., both are auditory, or both are visual) and have physically similar forms.', example: 'See BACB Task List for Formal Similarity.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-016', term: 'Generic Tact Extension', definition: 'An extended tact in which a response is controlled by a novel stimulus that is a member of the same general stimulus class as the original training stimulus, occurring because the novel stimulus shares defining features of that class.', example: 'See BACB Task List for Generic Tact Extension.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-017', term: 'Hierarchical Relations', definition: 'In relational frame theory, relations of inclusion or subordination between stimuli (e.g., A is a type of B); the basis of categorical and taxonomic knowledge.', example: 'See BACB Task List for Hierarchical Relations.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-018', term: 'Imitation', definition: 'A behavior that is controlled by a model  --  a prior stimulus that has the same physical form as the imitative response; the observer\'s behavior topographically resembles the model\'s behavior and is reinforced by the social community for matching the model.', example: 'See BACB Task List for Imitation.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-019', term: 'Magical Mand', definition: 'A mand emitted under a strong motivating operation but in the absence of a listener who has the ability or willingness to provide the relevant reinforcer, such that the verbal response cannot actually produce the specified reinforcer.', example: 'See BACB Task List for Magical Mand.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-020', term: 'Metaphorical Tact Extension', definition: 'An extended tact in which a response is controlled by a novel stimulus that shares a property with the original training stimulus, even though the novel stimulus belongs to a different stimulus class.', example: 'See BACB Task List for Metaphorical Tact Extension.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-021', term: 'Metonymical Tact Extension', definition: 'An extended tact in which a response is controlled by a stimulus that was merely present at the same time as the original training stimulus, with no physical similarity between the two stimuli.', example: 'See BACB Task List for Metonymical Tact Extension.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-022', term: 'Point-to-Point Correspondence', definition: 'A formal property of verbal behavior in which each unit of the verbal response corresponds to a specific unit of the controlling stimulus, such that the sequence and form of the response mirrors the sequence and form of the stimulus.', example: 'See BACB Task List for Point-to-Point Correspondence.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-023', term: 'Response-Deprivation Hypothesis', definition: 'The principle that any behavior can function as a reinforcer if access to it is restricted below its baseline level; provides a behavioral account of reinforcement that does not require the concept of drive or need.', example: 'See BACB Task List for Response-Deprivation Hypothesis.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-024', term: 'Solistic Tact Extension', definition: 'An extended tact in which a response is controlled by a stimulus property that is only indirectly related to the proper tact relation, resulting in substandard or idiosyncratic verbal behavior such as malaprops, slang, or non-standard usage.', example: 'See BACB Task List for Solistic Tact Extension.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-025', term: 'Superstitious Mand', definition: 'A mand maintained by an accidental reinforcement history in which the verbal response was coincidentally followed by the relevant reinforcer, even though the response did not actually produce the reinforcer.', example: 'See BACB Task List for Superstitious Mand.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'sync2-026', term: 'Tact Extension', definition: 'A discrimination in which the correct response to a comparison stimulus depends on the value of a sample or contextual stimulus.', example: 'See BACB Task List for Tact Extension.', domain: 'B', domainFull: 'Concepts & Principles' },
  // End of sync entries
  { id: 'b-cer', term: 'Conditioned Emotional Response (CER)', definition: 'An emotional response (e.g., fear, anxiety, excitement) that is elicited by a conditioned stimulus that has been paired with an unconditioned stimulus; a form of respondent conditioning in which neutral stimuli acquire eliciting functions.', example: 'A child who was bitten by a dog shows fear responses (crying, avoidance) when seeing any dog — the sight of dogs has become a conditioned stimulus that elicits a conditioned emotional response through its pairing with the painful bite.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'b-delay-discounting', term: 'Delay Discounting', definition: 'The decrease in the subjective value of a reinforcer as the delay to its delivery increases; a reinforcer available immediately is valued more highly than the same reinforcer available after a delay; steep delay discounting is associated with impulsivity.', example: 'A student chooses a small immediate reward (one sticker now) over a larger delayed reward (five stickers tomorrow) — demonstrating delay discounting, in which the immediate reinforcer is valued more despite being objectively smaller.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'b-extinction-induced-variability', term: 'Extinction-Induced Variability', definition: 'An increase in the variability of behavior that occurs when a previously reinforced response is placed on extinction; the organism emits novel response topographies that were not previously reinforced, which can be captured and shaped toward a desired behavior.', example: 'A child whose tantrum behavior is placed on extinction begins trying new behaviors (asking, pointing, vocalizing) — the extinction-induced variability provides opportunities for the BCBA to differentially reinforce appropriate communication.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'g-generalization-programming', term: 'Generalization Programming', definition: 'The systematic application of strategies to promote the occurrence of trained behaviors in untrained settings, with untrained people, and under untrained conditions; includes training sufficient exemplars, training loosely, using indiscriminable contingencies, and programming common stimuli.', example: 'A BCBA teaches a child to greet peers in the therapy room, then systematically programs generalization by training in the classroom, on the playground, and at home, using multiple trainers and varied materials — generalization programming ensures the skill occurs across all relevant contexts.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'g-ncr', term: 'Noncontingent Reinforcement (NCR)', definition: 'A procedure in which a reinforcer is delivered on a fixed- or variable-time schedule, independent of the occurrence of any specific behavior; used as an antecedent intervention to reduce the motivating operation for problem behavior by providing free access to the maintaining reinforcer.', example: 'A BCBA identifies that a client\'s self-injury is maintained by attention; NCR is implemented by delivering attention every 3 minutes regardless of behavior, reducing the establishing operation for attention-maintained self-injury.', domain: 'G', domainFull: 'Behavior-Change Procedures' },
  { id: 'i-pyramidal-training', term: 'Pyramidal Training', definition: 'A staff training model in which a behavior analyst trains a small group of lead staff (trainers), who then train other staff under their supervision, creating a hierarchical dissemination structure that allows behavior-analytic skills to be distributed across large organizations efficiently.', example: 'A BCBA trains three senior RBTs in a new behavior intervention procedure; those three RBTs then train the remaining ten RBTs on their caseloads — pyramidal training disseminates the skill across the entire team without requiring the BCBA to train each individual directly.', domain: 'I', domainFull: 'Personnel Supervision & Management' },
  { id: 'b-renewal', term: 'Renewal (Context Renewal)', definition: 'The return of an extinguished behavior when the organism is placed in a context different from the one in which extinction occurred; a form of relapse that occurs because the extinction learning is context-specific and does not fully generalize to other environments.', example: 'A child\'s tantrum behavior is extinguished in the therapy room; when the child returns home, the tantrums recur — renewal occurs because the extinction learning was specific to the therapy context and did not transfer to the home environment.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'c-scatterplot', term: 'Scatterplot', definition: 'A data display method in which the occurrence of a target behavior is recorded within time intervals across the day on a grid, producing a visual pattern that reveals temporal distributions of behavior; used to identify times of day or conditions associated with high or low rates of behavior.', example: 'A BCBA uses a scatterplot to record a student\'s aggression across 30-minute intervals throughout the school day; the resulting pattern shows that aggression is concentrated in the morning before lunch, suggesting a possible establishing operation related to hunger.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'c-scatterplot-recording', term: 'Scatterplot Recording', definition: 'A data collection method in which the occurrence of a target behavior is recorded within time intervals across the day on a grid format, producing a visual display that reveals temporal patterns; used as an indirect or descriptive assessment tool to identify potential antecedent variables.', example: 'A BCBA implements scatterplot recording for a client\'s elopement behavior, dividing the school day into 15-minute intervals; after two weeks, the data reveal a consistent pattern of elopement during unstructured transition periods, guiding antecedent-based intervention planning.', domain: 'C', domainFull: 'Measurement, Data Display & Interpretation' },
  { id: 'f-stimulus-preference-assessment', term: 'Stimulus Preference Assessment', definition: 'A systematic procedure for identifying stimuli that an individual prefers and that may function as reinforcers; formats include single-stimulus, paired-stimulus (forced-choice), and multiple-stimulus with or without replacement (MSWO); preference does not guarantee reinforcer effectiveness.', example: 'A BCBA conducts a paired-stimulus preference assessment by presenting pairs of items and recording which item the client approaches; the items chosen most frequently are identified as high-preference stimuli and tested as potential reinforcers in a reinforcer assessment.', domain: 'F', domainFull: 'Behavior Assessment' },
  { id: 'b-tandem-schedule', term: 'Tandem Schedule', definition: 'A compound schedule of reinforcement in which the requirements of two or more component schedules must be completed in sequence before a reinforcer is delivered, without any distinctive stimuli signaling the transition between components; the absence of discriminative stimuli distinguishes it from a chained schedule.', example: 'A tandem FR5 FI30 schedule requires the organism to first complete 5 responses (FR component) and then wait 30 seconds (FI component) before a reinforcer is delivered, with no signal indicating when the FR requirement has been met and the FI component has begun.', domain: 'B', domainFull: 'Concepts & Principles' },
  { id: 'h-treatment-package', term: 'Treatment Package', definition: 'An intervention consisting of two or more components applied together as a unit; may be effective as a whole but requires component analysis to determine which elements are necessary and sufficient for the observed effects; common in applied settings where multiple procedures are combined for practical reasons.', example: 'A BCBA implements a treatment package for aggression that includes FCT, extinction, and NCR simultaneously; while the package is effective, a component analysis would be needed to determine which elements are responsible for the behavior change.', domain: 'H', domainFull: 'Selecting & Implementing Interventions' },


];

